// Üretilen dosya: tool/ozgun/uret.py. İstatistik ve Veri Bilimi · İstatistiksel yanılgılar ve veri okuryazarlığı (orta).
const ozStatistics13Orta = <(String, String, List<String>, String)>[
  ('İnsanlardan 100 atışlık sahte bir yazı-tura dizisi uydurmaları isteniyor. Gerçek rastgele dizilerle karşılaştırıldığında bu uydurma dizilerde en tipik eksiklik hangisidir?', 'Aynı yüzün art arda gelmesinden oluşan uzun serilerin çok az bulunması', ['Yazı ile turanın sayıca birbirine çok yakın çıkmaması, çünkü uydurma dizilerde sayılar çok farklı çıkar', 'Dizinin ilk yarısı ile ikinci yarısının tamamen aynı olması', 'Her atışın bir öncekiyle aynı çıkma eğiliminin güçlü olması'], 'İnsanlar rastgeleliği sürekli değişim sanır ve uzun aynı-yüz serilerinden kaçınır. Oysa gerçek rastgele dizilerde bu tür seriler şaşırtıcı sıklıkta görülür.'),
  ('6/49 sayısal çekilişinde 1-2-3-4-5-6 kombinasyonunun çıkma olasılığı ile 7-13-22-31-40-46 kombinasyonunun çıkma olasılığı hakkında hangisi doğrudur?', 'İkisi de eşittir ve her biri 1/13.983.816\'dır', ['Ardışık sayılar çok daha az olasıdır, çünkü düzenli görünürler', 'Dağınık kombinasyon daha olasıdır, çünkü seçenekleri daha çoktur', 'Ardışık kombinasyon biraz daha olasıdır, çünkü sayılar komşudur'], 'Her belirli altılı kombinasyon eşit olasılıklıdır; C(49,6) = 13.983.816 olduğundan her birinin olasılığı 1/13.983.816\'dır.'),
  ('İkinci Dünya Savaşı sırasında Londra\'nın güneyine düşen V-1 uçan bombalarının dağılımı, bazı bölgelerde kümelenme varmış izlenimi veriyordu. R. D. Clarke\'ın 1946 çözümlemesi bu görünümün hakkında ne gösterdi?', 'Vuruşlar rastgele (Poisson) dağılıma uyuyordu; kümeler şansla beklenirdi', ['Bombaların kümelendiği bölgeler önceden belirlenmiş hedeflerdi, çünkü kümeler kazara oluşmaz', 'Vuruşlar düzgün bir ızgara gibi dağılmış, kümeleşme hiç görülmemişti', 'Kümelenme yalnız nüfus yoğunluğunun yüksek olduğu mahallelerde ortaya çıkmıştı'], 'Clarke haritayı küçük karelere böldü ve karelerdeki vuruş sayılarının Poisson dağılımına uyduğunu buldu. Rastgele süreçler de gözle kümelenme gibi görünen yapılar üretir.'),
  ('Bir mahalledeki 12 hanede alışılmadık sayıda hastalık vakası saptanıyor ve çevre kirliliği suçlanıyor. Bu çıkarımın en önemli istatistiksel zayıflığı hangisidir?', 'Çok sayıda mahalle arasından şansla yüksek çıkan bir tanesi sonradan seçilmiş olabilir', ['Küçük mahallelerde hastalıkların hiç görülmemesi gerektiği, çünkü şans etkisi küçük gruplarda ortadan kalkar', 'Vaka sayısının hiçbir zaman şansla yüksek çıkamayacağı', 'Çevre kirliliğinin hastalık yaptığının hiçbir koşulda kanıtlanamayacağı'], 'Binlerce küçük bölgeye bakıldığında, hiçbir ortak neden olmasa da bazıları yalnızca rastlantıyla yüksek çıkar. Sonradan seçilen kümenin anlamlılığı bu nedenle abartılır.'),
  ('Bir yatırım fonu, piyasa endeksini art arda beş yıl geçmiş ve \'beceri\' kanıtı olarak sunulmuştur. Her yıl endeksi geçme olasılığı şansla %50 ise, başlangıçta 1000 fon varsa şansla kaç fonun beş yıl art arda geçmesi beklenir?', 'Yaklaşık 31 fon', ['Yaklaşık 5 fon', 'Yaklaşık 100 fon', 'Yaklaşık 200 fon'], 'Beş yıl art arda geçme olasılığı (1/2)^5 = 1/32\'dir; 1000 / 32 ≈ 31. Çok sayıda fon varken birkaçının şansla \'başarılı\' görünmesi kaçınılmazdır.'),
  ('Bir dolandırıcı 10.240 kişiye mektup gönderiyor; yarısına bir hissenin yükseleceğini, yarısına düşeceğini yazıyor. Her hafta yalnız doğru tahmin aldığı kişilere yeni mektup yolluyor. 10 hafta sonunda kaç kişi 10 tahminin hepsini doğru almış olur?', '10 kişi', ['20 kişi', '5 kişi', '102 kişi'], 'Her hafta alıcı sayısı yarıya iner: 10.240 / 2^10 = 10. Bu kişiler bir \'kâhinle\' karşı karşıya olduklarına inanır, oysa tahmin gerçekte rastgeledir ve eleme sonucu oluşmuştur.'),
  ('Bir kart destesinden iade edilmeden çekim yapılırken ilk 10 kartın kırmızı çıkması, sonraki kartın siyah olma olasılığını neden gerçekten artırır?', 'Çekimler bağımsız değildir; kalan destede siyahların oranı yükselmiştir', ['Kartların bir belleği vardır ve dengeyi sağlamaya çalışır, çünkü her çekimde deste dengelenir', 'Deste karıştırıldığı için her çekimin olasılığı sürekli değişir', 'İlk 10 kartın rengi ancak desteyi hileli yapar ve oranı bozar'], 'İadesiz çekimde deste her çekimle değişir; 26 siyah ve 16 kırmızı kalmışsa siyah olasılığı 26/42 olur. Kumarbaz yanılgısı bağımsız olaylar için yanlış, iadesiz çekim için ise kısmen haklıdır.'),
  ('Bir öğrenci \'Hilesiz paranın uzun vadede yazı oranı 1/2 olur; o hâlde 1000 atışın sonunda yazı ve tura sayıları tam eşit olmalıdır\' diyor. Bu iddia için hangisi söylenebilir?', 'Yanlıştır; yazı oranı 1/2\'ye yaklaşır ancak sayıların tam eşit olması çok olasılıklı değildir', ['Doğrudur; büyük sayılar yasası tam eşitliği garanti eder, çünkü sapmalar sonunda birbirini götürür', 'Doğrudur; ancak yalnızca atış sayısı bin ya da daha fazla ise', 'Yanlıştır; çünkü yazı oranı hiçbir zaman 1/2\'ye yaklaşmaz'], '1000 atışta tam 500 yazı gelme olasılığı yalnızca yaklaşık %2,5\'tir. Yasa, oranın yakınsadığını söyler; kesin eşitliği değil.'),
  ('Bir yatırım fonları veri tabanında, kapanan ya da başka bir fonla birleştirilen kötü performanslı fonlar zamanla listeden çıkarılıyor. Bugünkü listeden hesaplanan 20 yıllık ortalama getiri için hangisi beklenir?', 'Gerçekte yatırımcının elde ettiğinden daha yüksek çıkar', ['Gerçekte yatırımcının elde ettiğinden daha düşük çıkar', 'Gerçek ortalama getiriyle tam olarak aynı çıkar', 'Hesaplanamaz, çünkü fonların getirileri bağımsız değildir'], 'Listede yalnızca hayatta kalan fonlar kaldığı için başarısız örnekler eksiktir. Bu hayatta kalma yanlılığı ortalama getiriyi yapay biçimde yükseltir.'),
  ('Bir tarihçi \'Orta Çağ\'da ortalama yaşam süresi 30\'du, yani insanlar 30 yaşında yaşlanıp ölüyordu\' diyor. Bu yorum ortalamanın hangi özelliğini göz ardı ediyor?', 'Ortalama, bebek ve çocuk ölümleriyle aşağı çekilir; yetişkinler daha uzun yaşar', ['Ortalama her zaman medyandan küçük çıkar, çünkü ortalama uç değerleri hesaba katmaz', 'Ortalamanın yalnız tek tepeli dağılımlarda hesaplanabilmesi', 'Ortalama yaşam süresinin yalnızca kadınlar için tanımlanması'], 'Doğumda yaşam beklentisi, erken yaşlardaki yüksek ölüm oranlarından büyük ölçüde etkilenir. Çocukluğu atlatan birçok kişi 60-70 yaşlarına ulaşıyordu; ortalama bunu saklıyor.'),
  ('Bir hastanede ameliyat sonrası hayatta kalma süresi, yalnızca ilk haftayı atlatan hastalar üzerinden hesaplanırsa süre ortalaması nasıl etkilenir?', 'Erken ölenler dışarıda kaldığı için ortalama süre gerçekte olduğundan uzun görünür', ['Ortalama süre gerçekte olduğundan kısa görünür, çünkü erken ölenler ortalamaya büyük değer katar', 'Ortalama süre hiç değişmez', 'Ortalama süre hesaplanamaz hâle gelir'], 'Dışlanan hastalar en kısa yaşayanlardır; kalanlar seçilmiş, daha uzun yaşayanlardır. Böyle bir hesap hayatta kalma yanlılığının yeniden bir örneğidir.'),
  ('Bir spor kulübü \'Antrenman programımızı bitiren 100 sporcunun hepsi sezon sonunda daha güçlüydü\' diyor. Programı yarıda bırakıp ayrılan 60 sporcu hesaba katılmamıştır. Bu kanıtın güvenilirliği için en doğru yorum nedir?', 'Zayıf kanıttır; programdan ayrılanlar da hesaba katılmadıkça program etkisi abartılmış olabilir', ['Güçlü kanıttır; çünkü bütün tamamlayanlarda artış görülmüştür', 'Geçersizdir; çünkü sporcu sayısı 100\'dür ve çok küçüktür, ayrıca ayrılanlar hesaba hiç katılamaz', 'Güçlü kanıttır; çünkü programı bırakanların sayısı tamamlayanlardan azdır'], 'Programı bırakanlar büyük olasılıkla gelişme göstermeyenlerdir. Yalnız tamamlayanlara bakmak, sonucu olumlu yönde seçilmiş bir gruba dayandırır.'),
  ('Bir araştırmada düzenli vitamin kullananların kullanmayanlardan daha az hastalandığı görülüyor. Vitamin kullananların daha çok spor yaptığı ve daha sağlıklı beslendiği de biliniyor. Bu durum hangi kavramla açıklanır?', 'Sağlıklı kullanıcı yanlılığı', ['Hayatta kalma yanlılığı, yani yalnız yaşayanların analize girmesi', 'Ekolojik yanılgı', 'Kumarbaz yanılgısı'], 'Sağlık davranışları bir arada görüldüğü için, sağlıklı yaşam tarzına sahip kişiler hem vitamin alır hem hasta olmaz. Vitamin ile sağlık arasındaki ilişkiye bu karıştırıcı davranışlar karışır.'),
  ('Çalışan işçilerin ölüm oranı, aynı yaş grubundaki genel nüfusun ölüm oranından belirgin biçimde düşük çıkıyor. Bu bulgunun kaynağı olarak \'sağlıklı işçi etkisi\' ne anlama gelir?', 'Çalışabilecek kadar sağlıklı olanlar işte kalır, ağır hastalar işgücü dışındadır', ['İşin kendisinin her zaman sağlığı iyileştirmesi, çünkü çalışmak sağlığı doğrudan düzeltir', 'İşçilerin daha sık doktor kontrolüne gitmesi', 'Genel nüfusta ölüm oranının yanlış ölçülmesi'], 'İşgücü, hasta ve özürlü kişileri zaten dışarıda bırakır; çalışanlar sağlıklı bir seçilmiş gruptur. Bu nedenle işçiler ile genel nüfusu karşılaştırmak yanıltıcı olabilir.'),
  ('Bir şehirde hastaneye yatan kişilerin ölüm oranı evde kalan kişilerden yüksektir. \'Hastane insanı hasta eder\' sonucu neden çıkarılamaz?', 'Ağır hastalar zaten yatırılır; hastalık ağırlığı hem yatışı hem ölümü etkiler', ['Hastanelerin ölüm kayıtlarını hiç tutmaması, çünkü bu yüzden oran hesaplanamaz', 'Evde kalan kişilerin sayısının çok fazla olması', 'Hastane yatışının ölüm olasılığını hiç etkilememesi'], 'Yatış kararı hastalığın şiddetine bağlıdır; bu karıştırıcı değişken yüzünden hastane yatışı ile ölüm arasında yanıltıcı bir ilişki oluşur. Bu duruma endikasyon karıştırıcılığı denir.'),
  ('Bir kentte son beş yılda yeni açılan her park için yakındaki konut fiyatlarının arttığı görülüyor. Parkların fiyatları artırdığını söylemeden önce hangi karıştırıcı olasılık araştırılmalıdır?', 'Belediyenin parkları zaten değer kazanacak, gelişmekte olan mahallelerde açmış olması', ['Parkların büyüklüğünün metrekare olarak ölçülmüş olması, çünkü ölçü birimi fiyatları etkiler', 'Konut fiyatlarının yıllık olarak raporlanması', 'Parkların ağaç türlerinin çeşitliliği'], 'Park yerinin seçimi, fiyat artışına yol açan mahalle gelişimiyle ilişkili olabilir. Bu ortak etken iki değişkeni de etkileyip aralarında yanlış bir nedensellik izlenimi yaratır.'),
  ('Bir araştırma, kahve içenlerde akciğer kanserinin daha sık görüldüğünü bulmuştur. Aynı araştırma sigara içme durumuna göre ayrı ayrı bakıldığında kahve ile kanser arasındaki ilişkinin ortadan kalktığını göstermiştir. Bu sonuç ne anlama gelir?', 'Sigara, hem kahve içmeyi hem kanseri etkileyen bir karıştırıcıydı ve ilk ilişki sahteydi', ['Kahve, kanseri sigaradan daha çok artırmaktadır, çünkü kahve doğrudan akciğere zarar verir', 'Sigaranın kanserle ilgisi yoktur', 'Kahve kanserin ters nedenidir'], 'Sigara içenler kahveyi de daha çok içiyorsa ilişki sigara kaynaklıdır. Gruplara ayırdığımızda ilişkinin kaybolması, karıştırıcının etkisinin ayrıştırıldığını gösterir.'),
  ('Bir okul yöneticisi, kütüphaneye daha sık giden öğrencilerin notlarının daha yüksek olduğunu görüp kütüphane gitmeyi zorunlu kılıyor. Not artışı beklenen düzeyde gerçekleşmeyebilir. Bunun en olası nedeni nedir?', 'Kütüphaneye kendiliğinden gidenler zaten daha motive öğrencilerdir', ['Kütüphanenin yalnızca sabahları açık olması, çünkü açılış saatleri başarıyı belirler', 'Notların yüzdeyle değil puanla verilmesi', 'Kütüphane kitaplarının eski olması'], 'Motivasyon, hem kütüphane kullanımını hem notları artırır. Zorunlu kılmak motivasyonu değiştirmediği için gözlemsel ilişki aynı şiddette ortaya çıkmayabilir.'),
  ('K ilacı hafif hastalarda 10 kişiden 9\'una, ağır hastalarda 100 kişiden 30\'una; L ilacı hafif hastalarda 100 kişiden 80\'ine, ağır hastalarda 10 kişiden 2\'sine yaramıştır. Ağır ya da hafif olduğu belli bir hastaya hangi ilacı önermek mantıklıdır?', 'K ilacı, çünkü her hastalık düzeyinde başarı oranı daha yüksektir', ['L ilacı, çünkü toplam başarı oranı daha yüksektir, ve bireysel karar bu orana dayanır', 'İkisi de eşit değerdedir, çünkü toplam sayılar birbirine yakındır', 'L ilacı, çünkü hafif hastaların sayısı daha fazladır'], 'K, hafifte %90\'a karşı %80, ağırda %30\'a karşı %20 ile her grupta üstündür. L\'nin toplamdaki üstünlüğü (%74,5\'e karşı %35,5) yalnız hafif hastaların ona yığılmış olmasından gelir.'),
  ('Bir okulda her sınıf düzeyinde kız öğrencilerin sınavı geçme oranı erkeklerinkinden yüksektir. Okulun toplamında erkeklerin geçme oranının daha yüksek çıkması mümkün müdür?', 'Evet, erkekler geçme oranı yüksek sınıf düzeylerinde yoğunsa mümkündür', ['Hayır, çünkü genel oran her alt grup oranının altında ya da üstünde kalmak zorundadır', 'Hayır, çünkü ağırlıklı ortalama her zaman büyük gruba doğru çekilir', 'Evet, ancak yalnızca okulda kız sayısı erkek sayısına eşitse'], 'Toplam oran, alt grup oranlarının grup büyüklükleriyle ağırlıklandırılmış ortalamasıdır. Ağırlıklar iki cinste farklıysa toplam sıralama alt grup sıralamasının tersine dönebilir.'),
  ('Bir ürün %25 zamlandıktan sonra eski fiyatına döndürülmek isteniyor. Zamlı fiyattan yüzde kaç indirim yapılmalıdır?', '%20', ['%25, çünkü zam ve indirim aynı tabana uygulanır', '%15', '%30'], '100 TL zamla 125 TL olur; 100\'e dönmek için 25/125 = %20 indirim gerekir. Zam ve indirim farklı tabanlara uygulanır.'),
  ('Bir köyde yıllık hırsızlık sayısı 2\'den 5\'e çıkıyor ve yerel haber \'Hırsızlıklar %150 arttı\' diye veriliyor. Bu başlık için hangi değerlendirme en yerindedir?', 'Yüzde doğrudur, ancak küçük taban abartılı izlenim verir; mutlak sayı da verilmelidir', ['Yüzde yanlış hesaplanmıştır; artış %60\'tır, çünkü fark yanlış tabana bölünmüştür, ve bu hata başlığı geçersiz kılar', 'Yüzdeyle sunulan hiçbir artış güvenilir sayılamaz', 'Köyde hırsızlık sorunu çok ciddidir, çünkü %150 çok yüksektir'], '(5−2)/2 = %150 doğrudur, ancak sayı yalnızca üç artmıştır. Küçük tabanlarda yüzde değişimleri şansla bile çok büyük görünebilir.'),
  ('Bir lig ilk sezonunda yüksek performans gösteren genç bir futbolcunun ikinci sezonda gol sayısının düşmesi \'ikinci sezon sendromu\' diye anılıyor. Bu düşüşün hangi istatistiksel nedeni olabilir?', 'İlk sezonki olağanüstü sonuç kısmen şanstı; sonraki sonuç ortalamaya yaklaşır', ['Futbolcunun ikinci sezonda mutlaka yeteneğini kaybetmiş olması, çünkü yetenek zamanla azalır', 'İkinci sezonun her zaman daha kısa oynanması', 'Gol sayısının yalnız ilk sezon boyunca ölçülebilmesi'], 'Uç değerler beceri ve şansın bileşimidir; şans payı tekrarlanmaz. Bu yüzden olağanüstü bir başlangıcı, ortalamaya daha yakın bir sonuç izler.'),
  ('Bir kişi, ağrısının en şiddetli olduğu gün alternatif bir tedaviye başlıyor ve birkaç gün sonra ağrısı azalıyor. \'Tedavi işe yaradı\' demek için neden temkinli olunmalıdır?', 'Ağrı kendiliğinden dalgalanır; en kötü anda başlayan kişi ortalamaya döner', ['Ağrının hiçbir zaman kendiliğinden azalmaması, çünkü ağrı yalnız tedaviyle geçer', 'Tedavilerin her zaman yalnızca plasebo olması', 'Ağrının yalnızca sabahları ölçülebilmesi'], 'Kişiler genellikle belirtilerin zirvede olduğu anda tedaviye yönelir. Kontrol grubu olmadan, sonraki iyileşmenin tedaviden mi doğal gidişten mi geldiği ayırt edilemez.'),
  ('Bir gazete \'Yeni ilaç kalp krizi riskini %30 azaltıyor\' yazıyor. Kontrol grubunda 1000 kişiden 10\'u kalp krizi geçirirken ilaç grubunda 7\'si geçirmiştir. Bu ilaç için kaç kişinin tedavi edilmesi bir krizi önler?', 'Yaklaşık 333 kişi', ['Yaklaşık 30 kişi, çünkü göreli azalma %30\'dur', 'Yaklaşık 3 kişi', 'Yaklaşık 100 kişi'], 'Mutlak azalma 10/1000 − 7/1000 = 3/1000 = 0,003\'tür; NNT = 1/0,003 ≈ 333. Göreli azalma (%30) etkiyi büyük, mutlak azalma (binde 3) ise çok küçük gösterir.'),
  ('Bir haber \'İşlenmiş et yemek bağırsak kanseri riskini %18 artırıyor\' diyor. Ömür boyu başlangıç riski %6 ise, aynı artışla mutlak risk yaklaşık kaç puan yükselir?', 'Yaklaşık 1,1 yüzde puan', ['Yaklaşık 18 yüzde puan, çünkü mutlak artış göreli artışa eşittir', 'Yaklaşık 6 yüzde puan', 'Yaklaşık 0,1 yüzde puan'], '%6\'nın %18 fazlası 6 × 1,18 ≈ %7,1\'dir; mutlak artış yaklaşık 1,1 puandır. Göreli artış tek başına mutlak etkiyi göstermez.'),
  ('Bir ilaç, hastalık riskini göreli olarak yarıya indiriyor. Bu ilacın mutlak risk azalması hangi durumda daha büyüktür?', 'Başlangıç riski %40 olan hastalarda, %0,02 olanlara göre çok daha büyüktür', ['Başlangıç riski %0,02 olan hastalarda, %40 olanlara göre çok daha büyüktür, çünkü yüksek riskte etki hiç görülmez', 'İki durumda da aynıdır, çünkü göreli azalma %50\'dir', 'İlacın dozuna bağlıdır ve başlangıç riskinden bağımsızdır'], 'Mutlak azalma, başlangıç riskinin yarısıdır: %40\'ta 20 puan, %0,02\'de yalnızca 0,01 puan. Aynı göreli etki yüksek riskli grupta çok daha fazla kişiyi korur.'),
  ('Bir kan grubu nüfusun %2\'sinde bulunuyor. Olay yerinde bu kan grubu bulundu ve sanık da bu gruptan. \'Sanık %98 ihtimalle suçludur\' sonucunda hangi hata vardır?', 'P(delil | masum), P(suçlu | delil) gibi yorumlanmıştır', ['Yüzde yerine kesir kullanılmış olmasıdır', 'Kan grubunun hiçbir zaman delil sayılmamasıdır', 'Nüfusun yalnız %2\'sinin ölçülmüş olmasıdır, yani örneklem çok küçüktür'], 'Rastgele bir masumun bu gruba sahip olma olasılığı (%2), sanığın suçlu olma olasılığıyla aynı şey değildir. 50 bin kişilik bir kentte yaklaşık 1000 kişi bu kan grubundadır.'),
  ('Bir doktor, önceki bir yıla göre kalp hastalığı ölümlerinde %20 azalış görüyor ancak genel ölüm sayısının değişmediğini fark ediyor. Başka bir hastalık nedeniyle ölümlerin arttığı düşünülmektedir. Bu durum hangi ayrımı gerektirir?', 'Nedene özgü ve tüm nedenlerden ölüm oranını birlikte', ['Yalnızca nedene özgü oranlara bakmayı, çünkü diğer nedenler önemsizdir', 'Ölüm sayılarını hiç hesaba katmamayı', 'Sadece ortalama yaşı ölçmeyi'], 'Bir nedene bağlı ölümün azalması toplam ölüm sayısının azaldığı anlamına gelmez; ölümler başka nedenlere kayabilir. Gerçek yarar için toplam ölüm oranı da izlenmelidir.'),
  ('Bir araştırmacı, aslında hiçbir etkisi olmayan 20 farklı maddeyi birbirinden bağımsız olarak %5 anlamlılık düzeyinde sınıyor. En az bir maddenin yalnızca şansla \'anlamlı\' çıkma olasılığı yaklaşık kaçtır?', 'Yaklaşık %64', ['Yaklaşık %5', 'Yaklaşık %20', 'Yaklaşık %100'], 'En az bir yanlış pozitif olasılığı 1 − 0,95^20 ≈ 0,64\'tür. Tek bir test için %5 olan hata oranı, çok sayıda testte hızla yükselir.'),
  ('Bir çalışma, 20 farklı renkteki jelibonun her birini akneyle ilişkilendiriyor; yalnızca yeşil jelibon için p < 0,05 çıkıyor ve haber \'Yeşil jelibon aknenin nedeni\' oluyor. Bu sonuç hakkında en uygun değerlendirme hangisidir?', 'Yirmi test yapıldığı için şansla bir anlamlı sonuç beklenir', ['Tek bir p < 0,05 yeterlidir; yeşil jelibonun nedensel etkisi kanıtlanmıştır', 'Test sayısı fazla olduğundan hiçbir sonucun anlamlı olması mümkün değildir', 'Sonuç doğrudur, çünkü yeşil renk akneyle bilinen güçlü bir ilişki taşır'], '20 testte şansla en az bir p < 0,05 çıkma olasılığı yaklaşık %64\'tür. Çoklu karşılaştırma düzeltmesi yapılmadan tek bir anlamlı sonuç öne çıkarılamaz.'),
  ('Bir ilaç çalışmasında, ilaç genel olarak etkisiz bulunuyor; ardından araştırmacılar hastaları burç, yaş, cinsiyet, meslek gibi 15 ölçüte göre alt gruplara ayırıp her birinde test yapıyor. Bu alt grup avcılığının sonucu için hangisi beklenir?', 'Etki olmasa bile bir alt grupta şansla anlamlı sonuç çıkabilir', ['Alt grup sayısı arttıkça hiçbir sonucun anlamlı olmaması, çünkü her alt grup aynı kanıtı verir', 'Alt gruplarda etkinin her zaman genel sonuçla aynı çıkması', 'Alt grup analizlerinin her zaman gerçek etkileri bulması'], 'Her alt grup testi ek bir şans verir; düzeltme yapılmazsa yanlış pozitifler kaçınılmazdır. Bu yüzden alt grup bulguları ancak önceden planlandığında ve düzeltildiğinde güvenilirdir.'),
  ('2009\'da araştırmacılar ölü bir somon balığına fMRI taraması yapıp resimler göstererek beyin bölgelerinde \'etkinlik\' saptadılar. Bu çalışma neyi göstermek içindi?', 'Düzeltme yapılmazsa ölü dokuda bile sahte etkinlik bulunabileceğini', ['Balıkların ölümden sonra da düşünebildiğini, çünkü beyin etkinliği ölümden sonra sürer', 'fMRI cihazının hiçbir zaman çalışmadığını', 'Somonların resim tanıma yeteneğini'], 'Binlerce voksel bağımsız test edilince, hiçbir gerçek sinyal olmasa da bazıları anlamlı çıkar. Çalışma, çoklu karşılaştırma düzeltmesinin önemini vurgulamak için yapıldı.'),
  ('Bir ilaç denemesinde p = 0,049 bulunuyor ve ilaç \'etkili\', ikinci bir denemede p = 0,051 bulunuyor ve ilaç \'etkisiz\' ilan ediliyor. Bu karşılaştırma için hangisi doğrudur?', 'İki sonuç neredeyse aynı kanıt gücündedir; eşik zıt etiket vermiştir', ['Birinci deneme ikinciden çok daha güçlü bir kanıt sunar', 'İkinci deneme ilacın etkisiz olduğunu kesin biçimde kanıtlar', 'İki deneme, aynı anlamlılık düzeyinde olmadıkları için karşılaştırılamaz'], '0,049 ile 0,051 arasındaki fark kanıt bakımından önemsizdir; ikilik karar eşiği gerçek farkı olduğundan büyük gösterir. Etki büyüklüğü ve güven aralığıyla birlikte yorumlanmalıdır.'),
  ('Beş kişilik küçük bir deneme, tedaviyle 10 puanlık bir iyileşme gösteriyor ancak p = 0,12 çıkıyor. \'Tedavi etkisizdir\' sonucu neden uygun değildir?', 'Küçük örneklemde güç düşüktür; anlamsız sonuç etkinin yokluğunu kanıtlamaz', ['Küçük örneklemde p-değeri hep büyük olduğu için sonuç geçerlidir, çünkü büyük örneklem şarttır', 'Beş kişi hiçbir zaman örneklem sayılmaz', 'İyileşme puanlarının sayısal olması sonucu geçersiz kılar'], 'Anlamsız sonuç ancak \'etki yok\' demek için gereken gücün sağlandığı durumda anlamlıdır. Burada büyük bir etki gözlendi; güven aralığı çok geniş olacaktır.'),
  ('Yirmi bağımsız araştırma ekibi aynı etkisiz maddeyi test ediyor ve yalnız anlamlı sonuç bulan tek ekip makalesini yayımlıyor. Bu yayın hakkında hangisi doğrudur?', 'Yayın yanıltıcıdır; sonuç, 19 olumsuz çalışmayı gizleyen bir seçilimin ürünüdür', ['Yayın güvenilirdir, çünkü anlamlılık düzeyi %5\'ten küçüktür, ve p-değeri bunu doğrular', 'Yayın, madde etkisiz olsa bile gerçeğin ta kendisidir', 'Yayın ancak 20\'den fazla ekip aynı sonucu bulursa anlamlıdır'], 'Yirmi ekipten birinin şansla p < 0,05 bulması beklenen bir olaydır. Olumsuz sonuçlar yayımlanmadığında literatür yalnız yanlış pozitifleri gösterebilir.'),
  ('2015\'te yayımlanan bir çalışmada 100 psikoloji deneyi yeniden yürütüldü; özgün çalışmaların neredeyse tümü anlamlı sonuç bildirmişken yeniden yürütmelerde anlamlı sonuç oranı yaklaşık üçte bir düzeyinde kaldı. Bu bulgu hangi soruna işaret eder?', 'Tekrarlanabilirlik krizi; bazı sonuçlar şansla çıkmış olabilir', ['Psikolojinin bilimsel olamayacağı, çünkü deneyler hiçbir zaman tekrarlanamaz', 'İstatistiğin hiçbir zaman güvenilir olmadığı', 'Örneklem sayısının hiçbir zaman önemli olmadığı'], 'Düşük güç, yayın yanlılığı ve esnek analiz birlikte yayımlanmış etkileri abartır. Yeniden yürütmelerde etkilerin küçülmesi bu mekanizmaların izidir.'),
  ('Bir mağaza, Ocak ayında 100 olan satışların Aralık ayında 300\'e çıkmasını göstererek \'Bir yılda satışlarımız %200 arttı\' diyor. Mağaza bir hediyelik eşya satıcısıdır ve Aralık ayı yılbaşı sezonudur. Bu karşılaştırmanın hangi sorunu vardır?', 'Mevsimsellik göz ardı edilmiştir', ['Satış sayıları tam sayı olduğu için yüzde hesaplanamaz', 'Ocak ayı yılın ilk ayı olduğu için kıyaslanamaz', 'Yüzde artış hiçbir zaman iki aydan fazla dönemde hesaplanamaz'], 'Aylar arası değişimin bir kısmı düzenli mevsimsel dalgalanmadır. Gerçek büyüme için aynı sezonun yıllar arasında kıyaslanması ya da mevsimsellikten arındırılmış veri gerekir.'),
  ('1979\'da Lord, Ross ve Lepper, idam cezasını destekleyen ve karşı çıkan kişilere hem destekleyici hem çürütücü iki çalışma okuttu. Sonuçta iki grup da kendi görüşünü daha da pekiştirdi. Bu bulgunun adı nedir?', 'Tutum kutuplaşması', ['Kumarbaz yanılgısı, yani art arda olayların bağımlılığına inanmak', 'Ortalamaya dönüş', 'Simpson paradoksu'], 'İnsanlar kendi görüşünü destekleyen kanıtı güçlü, karşıtını kusurlu bulur. Aynı karışık kanıtı okuyan iki taraf bu yüzden birbirinden daha da uzaklaşabilir.'),
  ('Denes-Raj ve Epstein\'ın deneyinde katılımcılar kırmızı bilye çekerse ödül kazanıyor. A kavanozunda 10 bilyeden 1\'i, B kavanozunda 100 bilyeden 8\'i kırmızıdır. Birçok katılımcı bilinçli olarak B kavanozunu seçti. Bu eğilim hangi hatayı gösterir?', 'Oran yerine sayıya odaklanma', ['Kumarbaz yanılgısı, yani art arda olayların dengeleneceğine inanmak', 'Savcı yanılgısı', 'Texas keskin nişancı yanılgısı'], 'A\'da olasılık %10, B\'de %8\'dir; B kötü bir seçimdir. Birçok kişi 8 kırmızı bilyeyi 1\'den çok görüp paydayı ihmal eder.'),
  ('Bir maaş pazarlığında ilk rakamı işveren söylediğinde, çalışanın ondan sonra tartışılan miktarları genellikle bu ilk rakama yakın kalıyor. Bu durumda çalışanın çıpalamaya karşı korunmak için en uygun adımı hangisidir?', 'Kendi piyasa araştırmasıyla bağımsız bir aralık belirlemek', ['Teklif ne olursa olsun kabul etmek, çünkü ilk sayı en doğru değerdir', 'Karşı tarafın rakamına yakın bir sayı söylemek', 'Pazarlığa hiç katılmamak'], 'Bağımsız bir referans aralığı, rakipten gelen çıpanın etkisini zayıflatır. Önceden hazırlanan veri, ilk sayıya sürüklenmeyi azaltır.'),
  ('Bir araştırma, diyet içeceği tüketen kişilerin ortalamada daha kilolu olduğunu gösteriyor. Bu bulgudan \'diyet içeceği kilo aldırır\' sonucunun çıkarılmasına karşı en güçlü alternatif açıklama hangisidir?', 'Kilosundan endişe eden kişiler diyet içeceğini daha çok seçiyor olabilir', ['Diyet içeceğinin hiçbir zaman tüketilmemesi nedeniyle ilişkinin tesadüfi olması', 'Kilolu kişilerin yalnızca geçmiş yıllarda ölçülmüş olması nedeniyle verinin güncel olmaması', 'Diyet içeceklerinin kalorisinin sıfır olması nedeniyle ilişkinin ölçülememesi'], 'Zayıflamak isteyenler diyet ürünlerine yönelir; yani kilo, içecek tercihine yol açıyor olabilir. Yön, gözlemsel ilişkiden çıkarılamaz.'),
  ('Sigorta sahibi olan kişilerin kaza yapma oranının sigortası olmayanlardan yüksek çıktığı görülüyor. Bu ilişkiyi \'sigorta insanları dikkatsiz yapar\' demeden açıklayabilecek mekanizma hangisidir?', 'Riskli olduğunu bilen kişilerin sigorta yaptırmaya daha istekli olması', ['Sigorta şirketlerinin kazaları kendi aralarında paylaşması nedeniyle oranın yükselmesi', 'Sigorta olmayanların kazalarının kayıt altına alınmaması nedeniyle oranın düşük görünmesi gerekmesi', 'Sigorta primlerinin yıllık değişmesi nedeniyle kazaların rastgele dağılması'], 'Risk kişiyi sigortaya iter; yani neden-sonuç yönü ters olabilir. Bu tür seçilim, ters nedensellik ya da olumsuz seçilim olarak adlandırılır.'),
  ('Matthews (2000), Avrupa\'daki 17 ülkede leylek çifti sayısı ile doğum sayısı arasında anlamlı pozitif bir ilişki buldu ve p-değeri 0,008 çıktı. Gerçekte ilişkiyi yaratan en olası etken nedir?', 'Ülkenin büyüklüğü: geniş ülkelerde hem leylek hem doğum fazladır', ['Leyleklerin bebek getirmesi', 'Doğumların leylek sayısını azaltması', 'Tamamen rastgele bir eşleşme olan ölçüm hatası, yani iki sayı tamamen bağımsızdır ve veri hatalıdır'], 'Ülke yüzölçümü ya da nüfus, iki sayının da büyüklüğünü belirler. Bu ortak neden, doğrudan nedensellik olmadan güçlü bir korelasyon üretir.'),
  ('Yıllar içinde sürekli artan iki ilişkisiz seri (örneğin bir ülkedeki çikolata tüketimi ve internet kullanıcı sayısı) arasında korelasyon hesaplanıyor ve çok yüksek çıkıyor. Bu yüksek korelasyonun ana kaynağı nedir?', 'İki serinin ortak bir zaman eğilimi taşıması', ['İki serinin birbirinin doğrudan nedeni olması', 'Serilerin tam sayı değerleri içermemesi', 'Seri uzunluğunun yılla değil ayla ölçülmesi'], 'Zamanla değişen herhangi iki değişken, ortak trend yüzünden ilişkili görünür. Farkları alarak ya da trendden arındırarak ilişki yeniden sınanmalıdır.'),
  ('Bir hastane, ameliyat sonrası ölüm oranına göre sıralanıyor ve yönetim bu oranı düşürmek için ameliyatı riskli hastaları kabul etmemeye başlıyor. Ölüm oranı düşüyor ancak tedaviye ulaşamayan hasta sayısı artıyor. Bu durum hangi ilkenin örneğidir?', 'Goodhart yasası; ölçüt hedef olunca amacı yansıtmaz', ['Ortalamaya dönüş; uç değerler zamanla normale gelir', 'Hayatta kalma yanlılığı; yalnız yaşayanlar sayılır', 'Büyük sayılar yasası; oranlar uzun vadede sabitlenir'], 'Ölüm oranı bir gösterge iken hedef olunca oynanır; riskli hastaları dışlamak göstergeyi iyileştirir ama gerçek bakım kalitesini düşürür.'),
  ('Bir üniversitenin başarısı yılda yayımlanan makale sayısına göre değerlendirilince bölümlerin bir bölümü aynı bulguyu birçok küçük makaleye bölmeye başlıyor. Bu \'salam yayıncılık\' hangi sorunla ilgilidir?', 'Göstergenin amaçla bağının kopması', ['Seçilim yanlılığının yayın sayısını azaltması', 'Örneklem büyüklüğünün makale sayısını belirlemesi', 'Standart sapmanın yayın kalitesini ölçmesi'], 'Makale sayısı bilimsel değerin kaba bir göstergesiydi; ödül ölçüte bağlanınca ölçütü şişirmek kolaylaşır. Bu, Goodhart yasasının tipik bir örneğidir.'),
  ('Bir küçük tatil kasabasında nüfus 2.000 iken yazın 40.000 turist gelmektedir. Suç oranı yalnızca kalıcı nüfus üzerinden hesaplandığında \'kişi başına suç\' nasıl görünür?', 'Olduğundan yüksek görünür; paydada turistler yoktur', ['Olduğundan düşük görünür, çünkü paydada turistler fazladır', 'Gerçekte olduğu kadar görünür, çünkü turistler hiç suç işlemez', 'Hesaplanamaz hâle gelir, çünkü nüfus değişkendir'], 'Suçun hem kurbanı hem faili olabilen turistler payda dışında kaldığından oran şişer. Doğru payda, ilgili riskin altındaki gerçek nüfustur.'),
  ('Bir araştırmacı 2.000 kişilik bir şehirde son yıl 4 hırsızlık, 100.000 kişilik başka bir şehirde 50 hırsızlık olduğunu görüyor. \'Küçük şehir 100 bin kişide 200 olay ile daha tehlikelidir\' sonucu hakkında hangisi söylenebilir?', 'Küçük payda nedeniyle oran çok oynaktır; 4 olay güvenilir değildir', ['Hesap kesindir, oran küçük şehirde mutlaka yüksektir, çünkü oran yalnız bir kez hesaplanır', 'Sonuç yanlıştır çünkü küçük şehirlerde hiç hırsızlık olmaz', 'Sonuç yalnızca şehir büyükse geçerlidir'], '4/2000 = 100 binde 200, 50/100000 = 100 binde 50\'dir; ancak 4 olaylık bir sayı şansla kolayca değişir. Küçük paydalı oranlar oynaktır ve dikkatle yorumlanmalıdır.'),
  ('Bir çalışanın maaşı bir yılda %20 artıyor, aynı dönemde fiyatlar %25 artıyor. Çalışanın satın alma gücü (reel maaşı) nasıl değişmiştir?', 'Yaklaşık %4 azalmıştır', ['Yaklaşık %5 artmıştır, çünkü maaş artışı fiyat artışından küçüktür ama faiz işler', 'Yaklaşık %5 azalmıştır, çünkü iki oranın farkı doğrudan alınır', 'Hiç değişmemiştir, çünkü iki oran birbirini dengeler'], 'Reel değişim 1,20 / 1,25 = 0,96\'dır; satın alma gücü %4 düşmüştür. Yüzdeleri doğrudan çıkarmak (−5) yaklaşık, ancak kesin olmayan bir sonuç verir.'),
  ('Bir ülkede asgari ücret 10 yılda 500 TL\'den 2.000 TL\'ye çıkarken aynı dönemde genel fiyat düzeyi 5 kat artmıştır. Asgari ücretin satın alma gücü hakkında hangisi doğrudur?', '%20 azalmıştır', ['4 kat artmıştır', 'Hiç değişmemiştir', '%25 artmıştır'], 'Nominal ücret 4 katına, fiyatlar 5 katına çıkmıştır; reel ücret 4/5 = 0,8 katına iner. Nominal artış büyük görünse de alım gücü düşmüştür.'),
  ('1939 yapımı bir sinema filmi, rekor listelerinde en çok hasılat yapan filmler arasında yer almıyor; enflasyona göre düzeltilmiş listede ise en üst sıralarda görünüyor. Bu farkın nedeni nedir?', 'Eski biletler ucuz olduğundan nominal hasılat düşüktür; düzeltme bunu giderir', ['Eski filmlerin yalnızca düşük sayıda izleyiciye ulaşması nedeniyle ortalamaları yüksek çıkar', 'Enflasyon düzeltmesinin hasılatı her zaman yarıya indirmesi', 'Düzeltilmiş listelerin yalnızca yabancı filmleri içermesi'], 'Parasal tutarlar farklı yıllarda farklı alım gücüne sahiptir. Çağlar arası karşılaştırmada nominal değerler yerine sabit fiyatlı değerler kullanılmalıdır.'),
  ('Bir tüketici fiyat sepetinde gıdanın ağırlığı %50, ulaşımınki %50\'dir. Gıda fiyatları %10 artıyor, ulaşım fiyatları değişmiyor. Genel fiyat endeksi yaklaşık yüzde kaç artar?', '%5', ['%10', '%0', '%7,5'], 'Genel artış, ağırlıklı ortalamadır: 0,50 × 10 + 0,50 × 0 = %5. Yalnızca gıda harcayan bir kişi için enflasyon %10 olurdu.'),
  ('Bir endeksin baz yılı 2000\'den 2010\'a kaydırılıp yeniden 100 yapılıyor. Bu değişiklikten sonra 2015 ile 2020 arasındaki yüzde değişim için ne söylenebilir?', 'Yüzde değişim aynı kalır', ['Yüzde değişim baz yılına bağlı olarak artar', 'Yüzde değişim yeni baz yılında sıfır olur', 'İki yıl arasında karşılaştırma yapılamaz hâle gelir'], 'Baz yılı değişimi bütün endeks değerlerini aynı sabitle çarpar; oran sabit kalır. Düzey değişse bile iki yıl arasındaki göreli değişim değişmez.'),
  ('1 milyon saniye ile 1 milyar saniye arasındaki fark çoğu insanca küçümsenir. 1 milyon saniye ve 1 milyar saniye sırasıyla yaklaşık ne kadar süredir?', 'Yaklaşık 11,6 gün ve yaklaşık 31,7 yıl', ['Yaklaşık 1 gün ve yaklaşık 1 yıl', 'Yaklaşık 11,6 saat ve yaklaşık 31,7 gün', 'Yaklaşık 12 gün ve yaklaşık 3,2 yıl'], '1.000.000 / 86.400 ≈ 11,6 gün; 1.000.000.000 / (86.400 × 365,25) ≈ 31,7 yıldır. Büyük sayıların sezgisel büyüklüğü zayıftır; ölçeklendirme yardımcı olur.'),
  ('0,1 mm kalınlığında bir kâğıt 42 kez ikiye katlanabilseydi toplam kalınlığı yaklaşık kaç kilometre olurdu?', 'Yaklaşık 440.000 km, Ay\'a olan uzaklıktan fazla', ['Yaklaşık 4.400 km, Dünya yarıçapı kadar, yaklaşık bir okyanus genişliği', 'Yaklaşık 44 km, bir dağ kadar', 'Yaklaşık 4,4 km, bir gökdelen kadar'], 'Kalınlık 0,1 mm × 2^42 ≈ 4,4 × 10^11 mm ≈ 440.000 km\'dir; Ay\'a olan uzaklık yaklaşık 384.000 km\'dir. Üstel büyüme, sezgilerin çok ötesinde sonuçlar verir.'),
  ('Satranç tahtasının ilk karesine 1, sonraki her kareye bir öncekinin iki katı kadar pirinç tanesi konuyor. Dördüncü kare 8 tane içerir. 64 karenin tümünde toplam kaç tane olur?', '2^64 − 1, yani yaklaşık 1,8 × 10^19 tane', ['Yaklaşık 64 × 64 = 4.096 tane', 'Yaklaşık 64 × 2 = 128 tane', 'Yaklaşık 2^32, yani 4,3 milyar tane, son karenin değeri kadar'], 'Toplam 1 + 2 + ... + 2^63 = 2^64 − 1 ≈ 1,8 × 10^19\'dur. Üstel dizilerde son terim, öncekilerin toplamından büyüktür.'),
  ('Bir haber ajansı \'Dünya nüfusu şu an tam olarak 8.012.345.678 kişidir\' diyor. Bu tür bir rakam hakkında hangisi söylenebilir?', 'Belirsizlik milyonlarca kişi olduğundan son basamaklar anlamsızdır', ['Bu rakam her an kesin olarak sayılabilen bir sayımdır', 'Dünya nüfusunun hiçbir koşulda tahmin edilememesi nedeniyle yanıltıcıdır', 'Tüm dünya hükümetlerinin nüfusu eşzamanlı saymasıyla elde edilir'], 'Dünya nüfusu modellerle tahmin edilir ve belirsizliği milyonlarca kişidir. Birimlere kadar giden rakam sahte bir kesinlik duygusu verir.'),
  ('Bir seçim anketinde A adayı %48, B adayı %45 çıkıyor ve haberde \'hata payı ±3 puan\' yazıyor. \'A önde\' manşeti için en doğru değerlendirme hangisidir?', 'Fark, hata payı içinde kaldığından A\'nın gerçekten önde olduğu kesinleşmez', ['Fark pozitif olduğundan A kesin biçimde öndedir ve hata payı yalnız bu farkı etkilemez', 'Hata payı yalnızca aday oyları toplamı %100 olmadığında anlam taşır', 'İki adayın oyları arasındaki farkın hata payı, her adayın payının hata payıyla aynıdır'], 'Her payın hata payı ±3 iken iki pay arasındaki farkın belirsizliği yaklaşık iki katıdır. 3 puanlık fark sınırlı kanıttır; sonuç \'baş başa\' olarak yorumlanır.'),
  ('1000 kişilik bir ankette genel hata payı yaklaşık ±3,1 puandır. Aynı anketin 100 kişilik bir alt grubu (örneğin 18-24 yaş) için hata payı yaklaşık ne olur?', 'Yaklaşık ±9,8 puan', ['Yaklaşık ±3,1 puan, çünkü hata payı örneklemden bağımsızdır', 'Yaklaşık ±0,3 puan', 'Yaklaşık ±31 puan'], 'Hata payı örneklem büyüklüğünün karekökü ile ters orantılıdır: n = 100 için 1,96 × √(0,25 / 100) ≈ 0,098. Alt grup bulguları genel sonuçtan çok daha az kesindir.'),
  ('Bir turizm ilinin gelirleri, bir bayramın bir yıl nisan ayına, ertesi yıl mayıs ayına denk gelmesi nedeniyle nisanda %25 düşüyor. Haber \'turizm çöküyor\' diyor. Bu yorumdaki temel sorun nedir?', 'Takvim (bayram kayması) etkisi göz ardı edilmiştir', ['Turizm gelirlerinin yalnızca yıllık ölçülebilmesi nedeniyle aylık verinin geçersiz olması', 'Nisan ayının her zaman diğer aylardan kısa olması nedeniyle düşüşün kaçınılmaz olması', 'Gelirlerin yüzde olarak değil ham sayıyla verilmesi nedeniyle yorumun geçersiz olması'], 'Hareketli tatiller gelirlerin aylar arasında kaymasına yol açar. Takvim ve mevsim etkilerinden arındırılmış ya da birkaç aylık toplamlar üzerinden karşılaştırma gerekir.'),
  ('Bir işsizlik oranı bir ay %9,8\'den %9,9\'a çıkıyor ve haber \'İşsizlik tırmanıyor\' diye veriliyor. Anketle ölçülen ve ±0,2 puan örnekleme hatası taşıyan bu oran için en uygun yorum hangisidir?', '0,1 puanlık değişim ölçüm gürültüsü içinde kalabilir', ['Değişim kesin bir artış gösterdiğinden eğilim açıktır ve hatayla ilgisi yoktur', 'Anket yöntemiyle ölçülen oranlar hiçbir zaman değişemez', 'Yüzde onluk basamaklar anlamlı olduğundan iki ay arası değişim kesindir'], 'Fark, bildirilen hata payından küçüktür. Birkaç aylık hareketli ortalama gibi daha uzun dönemli göstergeler gerçek eğilimi daha iyi yansıtır.'),
  ('Bir ülkenin turizm geliri 2020\'de pandemi nedeniyle %70 düştü ve 2021\'de bir önceki yıla göre %100 arttı. Bu artışın yorumunda hangi tuzağa dikkat edilmelidir?', 'Düşük taban etkisi: gelir 2019 düzeyinin hâlâ altında olabilir', ['Yüzde artışın hiçbir zaman %100\'ü geçememesi, çünkü artış tabanla sınırlıdır', 'Gelirlerin yalnızca ihracatla ölçülmesi', '2021\'in 2020\'den kısa bir yıl olması'], '100\'den 30\'a düşen bir değer, iki katına çıksa 60 olur ve eski düzeyin hâlâ %40 altındadır. Düşük tabana göre yüzde artışlar yanıltıcı biçimde büyük görünür.'),
  ('Bir şirketin satışları son iki yıl %40 büyüdü ve yönetici \'önümüzdeki on yıl da yılda %40 büyüyeceğiz\' diyor. Bu doğrusal olmayan ekstrapolasyonun temel kusuru nedir?', 'Geçmiş büyüme oranı sınırsız sürdürülemez; pazar doygunluğu sınırlar', ['Büyüme oranlarının yalnızca ay bazında yorumlanabilmesi', 'Yönetici dışında kimsenin gelecek hakkında tahmin yapamaması', 'İki yıllık verinin yüzde olarak ifade edilemeyecek kadar küçük olması'], 'Bir eğilimin gözlendiği dönemin ötesine taşınması, süreci sınırlayan etkenleri yok sayar. %40 büyümeyle on yılda satış yaklaşık 29 katına çıkardı; bunun gerçekçi olup olmadığı sorgulanmalıdır.'),
  ('Psikoloji deneylerinin çoğunun Batılı, eğitimli, sanayileşmiş, zengin ve demokratik toplumlardan (WEIRD) üniversite öğrencileriyle yapılması neyi sınırlar?', 'Başka toplumlara genellenebilirliği', ['Deneylerin bağımsız değişkenini ölçme olanağını', 'Verilerin sayısal biçime dönüştürülmesini', 'Deney sonuçlarının hiçbir zaman yayımlanabilmesini'], 'Henrich ve arkadaşlarının 2010 çalışması, örneklemin dar bir toplum diliminden gelmesinin bulguların evrensel olduğu varsayımını zayıflattığını gösterir. İç geçerlik yüksek olsa da dışsal geçerlik sınırlı olabilir.'),
  ('1920\'lerde Hawthorne fabrikasında yapılan çalışmalarda ışık şiddeti artırılınca da azaltılınca da işçilerin verimi yükseldi. Bu bulgu en çok hangi etkiyi akla getirir?', 'Gözlenmenin davranışı değiştirmesi', ['İşçilerin hiçbir koşulda çalışmayı bırakmaması', 'Fabrikalardaki elektrik tüketiminin hep artması', 'Işık şiddetinin üretimle doğrusal ilişkili olması'], 'Verim artışı ışık şiddetinden çok, işçilerin ilgi gördüklerini fark etmesiyle ilişkili görüldü. Katılımcı davranışı, gözlenme bilgisinden etkilenebilir.'),
  ('Bir sağlık kampanyasında katılımcılar kendi istekleriyle programa yazılıyor ve katılanlar katılmayanlardan daha çok kilo veriyor. Programın etkisini bu karşılaştırmayla ölçmek neden güvensizdir?', 'Gönüllüler zaten daha motive olabilir; gruplar baştan farklıdır', ['Gönüllü katılımın deneylerde yasak olması, çünkü gruplar hep eşittir', 'Katılanların sayısının her zaman katılmayanlardan fazla olması', 'Kilonun yalnızca doktor tarafından ölçülebilmesi'], 'Motivasyon hem katılımı hem kilo vermeyi etkileyen bir karıştırıcıdır. Rastgele atama olmadan program etkisi, motivasyon farkından ayrıştırılamaz.'),
  ('Bir çalışma, laboratuvarda 10 dakikalık bir görevde başarıyı ölçüyor ve sonucu \'gerçek hayatta insanların kararları böyledir\' diye genelliyor. Hangi geçerlilik sorunu söz konusudur?', 'Ekolojik geçerlilik sorunu vardır', ['Ölçüm geçerliliği; ölçeğin sayısal olmaması', 'Örnekleme hatası; katılımcı sayısının sonsuz olması', 'Karıştırıcı kontrol; rastgele atamanın olmaması'], 'Yapay görev ve ortam, gerçek yaşam koşullarını temsil etmeyebilir. İç geçerlik güçlü olsa bile bulgunun gerçek dünyaya aktarımı kanıtlanmamıştır.'),
  ('Bir meta-analiz, \'bir müdahalenin etkisi genel olarak küçüktür\' sonucuna varıyor, ancak yalnızca 18-25 yaş arası üniversite öğrencilerini içeren çalışmaları derlemiştir. Bulgunun ileri yaş grupları için geçerliliği hakkında ne söylenebilir?', 'Genellenebilirlik belirsizdir', ['Sonuç kesinlikle yaşlılar için de aynıdır', 'Sonuç yaşlılarda tam tersi yönde olmak zorundadır', 'Meta-analiz sonuçları hiçbir zaman genellenemez'], 'Çıkarım, çalışmaların kapsadığı popülasyonla sınırlıdır. Temsil edilmeyen gruplara genelleme varsayımdır, kanıtlanmış bir sonuç değildir.'),
  ('Bir nehir için \'100 yıllık taşkın\' ifadesi, her yıl %1 olasılıkla gerçekleşen bir taşkını anlatır. Bu bilgiye göre 30 yıllık bir sürede böyle bir taşkının en az bir kez görülme olasılığı yaklaşık kaçtır?', 'Yaklaşık %26', ['Yaklaşık %30\'dur', 'Yaklaşık %1\'dir, çünkü yıllık olasılık sabittir', 'Yaklaşık %74\'tür'], 'Hiç görülmeme olasılığı 0,99^30 ≈ 0,74\'tür; en az bir kez görülme olasılığı 1 − 0,74 ≈ 0,26\'dır. Yıllık olasılıkları doğrudan toplamak yaklaşık ve hatalı bir sonuç verir.'),
  ('Bir hindiye 1000 gün boyunca her gün yem veriliyor; hindinin \'tüm verilerime göre yarın da beslenirim\' çıkarımı 1001. gün Şükran Günü\'nde çöküyor. Bu hikâye istatistiksel çıkarım hakkında neyi vurgular?', 'Geçmiş düzenlilik, görülmemiş büyük olayı dışlamaz', ['Yeterince büyük örneklemin her tahmini kusursuz yaptığını', 'Hindilerin bağımsız karar alamadığını', 'Besin miktarının günlük olarak ölçülmemesi gerektiğini'], 'Bertrand Russell\'ın tavuk örneğini Nassim Taleb\'in popülerleştirdiği hikâye, uç ve nadir olayların geçmiş örneklemde bulunmayabileceğini anlatır. Uzun bir sakin dönem, güvenli bir geleceği kanıtlamaz.'),
  ('Bir kişi, yanıtlarından %90 emin olduğunu söylediği 100 genel kültür sorusunun yalnızca 65\'ini doğru yanıtlıyor. Bu durum için doğru yorum hangisidir?', 'Aşırı güven; güven doğruluktan yüksektir', ['Eksik güven; kişi kendi bilgisini küçümsemektedir', 'İyi kalibrasyon; güven ile doğruluk uyumludur', 'Hesaplama hatası; %90 ile %65 aynı anlama gelir'], 'İyi kalibre bir kişi %90 güvendiği yanıtların yaklaşık %90\'ında haklı olmalıdır. %65 doğruluk, güvenin bilgiden daha yüksek olduğunu, yani aşırı güveni gösterir.'),
  ('Her ameliyatta komplikasyon olasılığı %2 ve olaylar bağımsızdır. Bir hastanın 5 ameliyat geçirmesi durumunda en az bir komplikasyon yaşama olasılığı yaklaşık kaçtır?', 'Yaklaşık %9,6', ['Yaklaşık %10, çünkü olasılıklar basitçe toplanır', 'Yaklaşık %2', 'Yaklaşık %0,01'], 'Hiç komplikasyon olmama olasılığı 0,98^5 ≈ 0,904\'tür; en az bir komplikasyon olasılığı yaklaşık 0,096\'dır. Küçük risklerin tekrarı birikir ama doğrudan toplanmaz.'),
  ('Bir tarama testinin yanlış pozitif oranı %5\'tir. Hasta olmayan bir kişi bu testi birbirinden bağımsız 10 kez tekrarlarsa en az bir kez yanlış alarm alma olasılığı yaklaşık kaçtır?', 'Yaklaşık %40', ['Yaklaşık %5', 'Yaklaşık %50', 'Yaklaşık %0,0001'], 'En az bir yanlış alarm olasılığı 1 − 0,95^10 ≈ 0,40\'tır. Tekrarlanan testler, küçük yanlış alarm oranlarını birikimli olarak büyütür.'),
  ('Bir araştırmada ABD\'li sürücülerin yaklaşık %93\'ü kendini medyan sürücüden daha iyi olarak değerlendirdi (Svenson, 1981). Bu bulgu neden mantıksal olarak sorunludur?', 'Yarıdan fazlası medyanın üstünde olamaz', ['Sürücülerin gerçekte iyi olamaması', 'Medyanın hiçbir zaman hesaplanamaması', 'Anket yönteminin sürücü sayısını yanlış saymaması'], 'Medyanın üstünde olanların oranı en fazla yarıdır. %93 gibi bir oran, kendini üstün görme eğilimini (ortalamanın üstü etkisi) yansıtır.'),
  ('Bir okulda 20 öğrencinin puanlarının 19\'u 80, biri 0\'dır. Öğrencilerin yüzde kaçı aritmetik ortalamanın üzerinde puan almıştır ve bu durum medyanla ilgili ne gösterir?', '%95; ortalama aşırı düşük değerle çekilmiştir, medyan 80', ['%50; her veri setinde öğrencilerin tam yarısı ortalamanın üstündedir', '%5; çünkü yalnızca bir öğrenci farklıdır', '%100; çünkü ortalama medyandan büyük çıkar'], 'Ortalama (19 × 80)/20 = 76\'dır ve 19 öğrenci bunun üstündedir (%95). Ortalamanın üstünde olanların yarıdan çok olması, çarpık dağılımlarda mümkündür; medyanın üstünde ise en fazla yarısı olabilir.'),
  ('Bir şirket \'Çalışanlarımızın %70\'i ortalama maaşın üzerinde kazanıyor\' diye reklam yapıyor. Bu ifade için hangisi doğrudur?', 'Mümkündür; birkaç düşük maaş ortalamayı aşağı çekiyorsa', ['İmkânsızdır; çünkü ortalamanın üstü en fazla yarı olabilir', 'Mümkündür ancak yalnızca maaşlar tam olarak eşitse', 'İmkânsızdır; çünkü ortalama maaş her zaman medyanla aynıdır'], 'Sola çarpık dağılımlarda ortalama medyandan küçüktür ve çoğunluk ortalamanın üstünde kalır. Bu yüzden ifade, medyan ve dağılım bilgisi olmadan tek başına bilgilendirici değildir.'),
  ('Bir ülke işsiz tanımını, \'son 4 haftada iş arayan\' ölçütünden \'son 2 haftada iş arayan\' ölçütüne daraltıyor. Aynı yılın verileri iki tanımla hesaplandığında işsizlik oranı için ne beklenir?', 'Dar tanımda daha düşük çıkar; seri kırılır', ['Dar tanımda daha yüksek çıkar; çünkü daha az kişi işsiz sayılır', 'İki tanımda da tam olarak aynı çıkar; çünkü gerçek işsiz sayısı değişmez', 'Her iki tanımda da hesaplanamaz; çünkü iş arama süresi ölçülemez'], 'Tanım daraldıkça işsiz sayılan kişi azalır ve oran düşer. Tanım değişikliği, gerçek değişimle karışabilen bir seri kırılması yaratır.'),
  ('Bir salgın sırasında günlük test sayısı üç katına çıkarıldığında doğrulanmış vaka sayısı da iki katına çıkıyor. Bu artış için hangisi söylenebilir?', 'Bir bölümü, daha çok testten kaynaklanabilir', ['Artış tamamen gerçek bulaşma artışını gösterir', 'Test sayısı vaka sayısını hiçbir zaman etkilemez', 'Bu artış, hastalığın zayıfladığının işaretidir'], 'Saptanan vaka sayısı hem bulaşmaya hem test kapsamına bağlıdır. Pozitiflik oranı gibi testten bağımsız göstergeler daha güvenilirdir.'),
  ('Bir bölgede yeni bir kanser kayıt sistemi kurulduktan sonraki ilk yıl vaka sayısı çok yüksek çıkıyor. Bu sıçramanın en olası nedeni nedir?', 'Önceden kaydedilmeyen vakalar sisteme girmiştir', ['Kayıt sisteminin hastalığı yaymış olması', 'Kanser vakalarının kayıt sisteminden bağımsız olarak iki katına çıkması', 'Kayıt sisteminin yalnızca sağlıklı kişileri içermesi'], 'Yeni ya da iyileştirilmiş kayıt, daha önce eksik sayılan vakaları görünür kılar. Sıçrama, gerçek artıştan çok kayıt kapsamındaki değişimi yansıtabilir.'),
  ('Bir kentte polis kayıtlarındaki aile içi şiddet vakalarının sayısı, bir bilinçlendirme kampanyasından sonra %40 artıyor. Bu artış için hangi yorum en dikkatlidir?', 'Bildirme isteği artmış olabilir', ['Şiddetin kesinlikle %40 arttığı', 'Polisin kayıt tutmayı bıraktığı', 'Şiddet vakalarının kampanya tarafından yaratıldığı'], 'Kayıtlı olay sayısı, gerçek olay sayısı ile bildirme oranının çarpımıdır. Bildirme eğilimi değişirse gerçek durum sabit kalsa da kayıtlar değişir.'),
  ('Bir meşrubat şirketi, ürünün kilo alımıyla ilişkisi olmadığını bildiren bir araştırmayı finanse ediyor. Bu çalışmayı değerlendirirken hangi tutum en mantıklıdır?', 'Çıkar çatışmasını not edip bağımsız doğrulamak', ['Finansmanı hiç önemsememek; sonuçlar kesin doğrudur', 'Sonuçların her durumda yanlış olduğunu varsaymak', 'Finansman bilgisi bulunmayan çalışmaları daha güvenilir saymak'], 'Finansman sonucun yanlış olduğunu kanıtlamaz, ancak yanlılık riskini artırır. Metodoloji incelenmeli ve bağımsız kaynaklarla karşılaştırılmalıdır.'),
  ('Bir araştırmacı ham veri yerine yalnızca yayımlanmış özet çizelgelere erişebiliyor ve yalnız ortalamalar bildiriliyor. Bu durumda yapılamayacak şey hangisidir?', 'Dağılımın biçimini kontrol etmek', ['Ortalamayı okumak', 'Sonucun yayımlandığı yılı öğrenmek', 'Verinin hangi birimde ölçüldüğünü öğrenmek'], 'Özet ölçüler dağılımı gizler: aynı ortalama çok farklı verilerden çıkabilir. Güvenilir inceleme için ham veri ya da en azından dağılım ölçüleri gerekir.'),
  ('1990\'larda bir araştırmacı, ABD nüfusunun yaklaşık %87\'sinin yalnızca posta kodu, doğum tarihi ve cinsiyet bilgisiyle tekil olarak belirlenebileceğini gösterdi. Bu bulgu veri gizliliği için neyi vurgular?', 'Ek özelliklerin birleşimi kişiyi tanımlayabilir', ['Posta kodunun hiçbir zaman toplanmaması gerektiği', 'Doğum tarihlerinin her zaman yanlış girildiği', 'Cinsiyet bilgisinin hiçbir veri setinde bulunmadığı'], 'Latanya Sweeney\'in çalışması, kimlik bilgisi çıkarılmış verilerin başka veri setleriyle eşleştirilerek yeniden kimliklendirilebileceğini gösterdi. Anonimleştirme yalnız adı silmekle sağlanmaz.'),
  ('Bir veri setinde her kaydın, belirleyici özellikler bakımından en az 5 kayıtla ayırt edilemez olması şartı aranıyor. Bu ilkeye ne ad verilir?', 'k-anonimlik', ['Rastgele atama', 'Büyük sayılar yasası', 'Bonferroni düzeltmesi'], 'k-anonimlikte her kayıt, belirleyici özellikleri aynı olan en az k−1 başka kayıtla birlikte bulunur; bu, bireyin tek başına ayırt edilmesini zorlaştırır.'),
  ('Bir hastanenin bekleme süresi için yönetici \'Ortalama bekleme 10 dakika\' derken hasta derneği \'Hastaların %10\'u 2 saatten fazla bekliyor\' diyor. Her ikisi de doğruysa hangi sonuca varılabilir?', 'Dağılım çarpıktır; ortalama uzun bekleyenleri gizler', ['Bir ifadenin yanlış olduğu', 'Tüm hastalar tam olarak eşit süre beklemektedir', 'Ortalama ile yüzdelikler hiçbir zaman birlikte verilemez'], 'Çoğu hasta kısa bekler, az bir kısmı çok uzun bekler; ortalama kısa görünür. Yüzdelikler ya da üst yüzdelik değerleri deneyimin tamamını daha iyi gösterir.'),
  ('Bir şirket kâr artışını %0,5 puan olarak, bir diğeri ise aynı artışı \'kâr %25 arttı\' diyerek anlatıyor (önceki kâr marjı %2). Bu iki ifade için hangisi doğrudur?', 'İkisi de doğrudur; mutlak ve göreli ölçü farklı görünür', ['Yalnızca ikincisi doğrudur, çünkü yüzde daha büyüktür', 'Yalnızca birincisi doğrudur, çünkü puan her zaman daha güvenilirdir', 'İkisi de yanlıştır, çünkü kâr marjı yüzdeyle anlatılamaz'], '%2\'den %2,5\'e çıkış 0,5 puandır ve göreli olarak %25\'tir. Hangi ölçünün seçildiği, aynı olgunun küçük ya da büyük görünmesini belirler.'),
  ('Bir ülkede ham kanser vakası sayısı son 30 yılda belirgin biçimde artmıştır ve nüfusun ortalama yaşı da yükselmiştir. Gerçek risk artışını ayırt etmek için hangi yöntem uygundur?', 'Yaşa göre standardize edilmiş oranları karşılaştırmak', ['Vaka sayılarını doğrudan toplamak, çünkü oranlar gereksizdir ve yanıltır', 'Yalnızca kentte yaşayanları incelemek', 'Sadece ortalama yaşa bakmak'], 'Yaş arttıkça kanser riski yükseldiğinden, yaşlanan nüfus ham sayıyı yapay olarak artırır. Standart bir yaş dağılımı kullanılarak hesaplanan oranlar, bu etkiyi ortadan kaldırır.'),
  ('Bir kesit araştırmada 70 yaş üstü kişilerin akıllı telefon kullanım oranı gençlerden çok düşük bulunuyor. \'İnsanlar yaşlandıkça telefon kullanmayı bırakıyor\' sonucu ne yönden eksiktir?', 'Kuşak (kohort) etkisi göz ardı edilmiştir', ['Telefon kullanımının hiç ölçülememesi', 'Yaşlıların sayıca az olması nedeniyle hiçbir sonuç çıkmaması', 'Gençlerin telefon kullanmaması'], 'Aynı anda farklı yaşlara bakan kesit veri, yaş etkisini kuşak etkisinden ayıramaz. Aynı kişileri zaman içinde izleyen boylamsal veri gerekir.'),
  ('Flynn etkisi, yirminci yüzyılda birçok ülkede zekâ testi puanlarının on yılda yaklaşık 3 puan arttığını bildirir. Bu bulgu farklı kuşakların aynı testteki puanlarının karşılaştırılması için neyi gösterir?', 'Çevresel koşulların etkisini', ['Testlerin hiçbir zaman kullanılamayacağını', 'Zekânın tamamen kalıtsal olduğunu', 'Testlerde hiçbir soru bulunmadığını'], 'Aynı testin farklı dönemlerde kuşaklar arası yükselmesi, kohort koşullarının sonuçları etkilediğini gösterir. Bu yüzden zaman içindeki karşılaştırmalarda kuşak etkisi göz önünde bulundurulmalıdır.'),
  ('Aynı yılda 20 yaşında, 40 yaşında ve 60 yaşında kişilere uygulanan bir anket yerine, aynı kişileri 40 yıl boyunca izleyen bir çalışma yapmanın başlıca avantajı nedir?', 'Değişimi doğrudan gözlemlemek', ['Katılımcı sayısının artması ve maliyetin düşmesi', 'Katılımcı kaybı sorununun ortadan kalkması', 'Çalışmanın bir yılda tamamlanabilmesi'], 'Boylamsal çalışmada aynı kişiler izlendiğinden kuşak farkı sabit kalır. Dezavantajı uzun sürmesi ve katılımcı kaybıdır.'),
  ('Bozuk bir terazi, her tartıda gerçek kütleden tam 2 kg fazla gösteriyor. Bu terazi ölçüm kalitesi açısından nasıl nitelendirilir?', 'Güvenilir ama geçersiz', ['Hem güvenilir hem geçerli', 'Ne güvenilir ne geçerli', 'Geçerli ama güvenilir değil'], 'Her tartıda aynı sapmayı gösterdiği için tutarlıdır (güvenilirlik yüksek); ancak doğru değeri ölçmediği için geçerli değildir.'),
  ('Bir araştırmacı, okul başarısını yalnızca öğrencilerin yıllık devamsızlık gün sayısıyla ölçüyor. Bu ölçüm için hangi eleştiri yerindedir?', 'Ölçülen şey ile ölçülmek istenen örtüşmüyor', ['Devamsızlık gün sayısı hiçbir zaman sayılamaz', 'Başarının tek göstergesi devamsızlıktır ve yeterlidir', 'Okul başarısı yalnızca öğretmenlerce ölçülebilir'], 'Başarı çok boyutlu bir kavramdır; devamsızlık ancak onunla ilişkili olabilecek dolaylı bir göstergedir. Yapı geçerliliği, ölçütün asıl kavramı ne kadar yakaladığını sorgular.'),
  ('Bir ilde en yüksek ve en düşük sınav ortalamasına sahip okulların birçoğunun küçük köy okulları olduğu görülüyor. Bu durum neye bağlanır?', 'Küçük okullarda ortalama çok dalgalanır', ['Küçük okulların öğretmenlerinin hem çok iyi hem çok kötü olması', 'Küçük okullarda sınavın hiç yapılmaması', 'Sıralamaların rastgele atanması'], 'Ortalamanın standart hatası örneklem büyüklüğüyle azalır; az öğrencili okullarda rastlantı etkisi daha büyüktür. Uç sıralar bu yüzden küçük okullarla doludur.'),
  ('Bir üniversite sıralamasında araştırma, eğitim ve uluslararasılık gibi göstergeler ağırlıklarla birleştiriliyor. Ağırlıklar değiştirilince üniversitelerin sıralaması da değişiyor. Bu durum için hangisi doğrudur?', 'Bileşik sıralama ağırlık seçimine duyarlıdır', ['Sıralama ağırlıklardan bağımsızdır', 'Ağırlık değişimi sıralamayı hiçbir zaman etkilemez', 'Sıralamanın değişmesi verinin yanlış olduğunu kanıtlar'], 'Bileşik endeksteki ağırlıklar değer yargısıdır; farklı seçimler farklı sıralar üretir. Sıralamalar, ölçütler ve ağırlıkları bilinerek yorumlanmalıdır.'),
  ('İki hastane, ameliyat sonrası ölüm oranına göre sıralanıyor; birinci hastane ağır hastaları kabul eden bir merkez, ikinci hastane ise hafif vakalara bakan bir merkezdir. Risk ayarlaması yapılmazsa sıralama için ne beklenir?', 'Ağır vaka kabul eden hastane haksız kötü görünür', ['Ağır vakaları kabul eden hastane her zaman daha iyi görünür', 'Sıralama vaka karışımından bağımsızdır', 'İkinci hastane her zaman kötü görünür'], 'Hasta karışımı sonuçları büyük ölçüde belirler; risk ayarlaması olmadan karşılaştırma haksız olur. Doğru sıralama, benzer riskteki hastalar arasında yapılmalıdır.'),
  ('Google Flu Trends adlı sistem, arama sorgularından grip yaygınlığını tahmin ediyordu; 2012-2013 sezonunda gerçek yaygınlığı iki kattan fazla abartmıştır. Bu başarısızlık büyük veri hakkında neyi gösterir?', 'Büyük veri yanlılıkları ortadan kaldırmaz', ['Veri ne kadar büyük olursa tahminin her zaman o kadar doğru olduğunu', 'Arama sorgularının hiçbir zaman ölçülemeyeceğini', 'Gribin gerçekte hiç bulunmadığını'], 'Lazer ve arkadaşlarının 2014 incelemesi, büyük veri kibrinin (big data hubris) örneği olarak bunu gösterdi. Arama davranışının değişmesi ve model uyumsuzluğu tahmini bozdu.'),
  ('Bir şirket, \'N = tüm müşteriler\' diyerek yalnızca kendi uygulaması üzerinden alışveriş yapanların verisini analiz edip \'tüm pazarın eğilimi\' diyor. Bu çıkarım hakkında hangisi doğrudur?', 'Kullanıcılar pazarın tümünü temsil etmeyebilir', ['Tüm veriye sahip olunduğu için çıkarım kesinlikle doğrudur', 'Kayıt dışı alışveriş yapanların hiç bulunmaması', 'Uygulama verisinin sayısal olmaması'], 'N = tümü yanılgısı, verinin kaydedildiği birimlerle ilgilenilen anakütleyi karıştırır. Kayıt dışı kalan müşteriler, pazarın önemli bir bölümü olabilir.'),
  ('Bir maliyet kalemi ilk yıl 20 bin liradır ve ertesi yıl \'%300 artışla\' yükseliyor. İkinci yıl maliyet kaç bin liradır?', '80 bin lira', ['60 bin lira', '100 bin lira', '120 bin lira'], '%300 artış, ilk değerin 3 katı kadar eklenmesidir: 20 + 60 = 80 bin lira, yani 4 katıdır. Yüzde artış ile \'kat\' sayısı arasında 1 fark vardır.'),
  ('Bir sınav A okulunda %20, B okulunda %30 başarı oranıyla sonuçlanıyor. Okulların birleşik başarı oranının %25 olması hangi koşulda doğru olur?', 'İki okulun öğrenci sayıları eşit olduğunda', ['Her zaman, öğrenci sayısından bağımsız olarak', 'Yalnızca A okulunun öğrenci sayısı B\'nin iki katı olduğunda', 'Yalnızca B okulu daha büyük olduğunda'], 'Birleşik oran, okulların büyüklüğüyle ağırlıklandırılmış ortalamadır. İki oranın basit ortalaması, ancak gruplar eşit büyüklükteyse birleşik orana eşittir.'),
  ('Bir ilaç firması \'Ürünümüz %99 doğru sonuç veriyor\' diyor. Hastalığın toplumda görülme oranı %0,1 ise pozitif çıkan bir kişinin gerçekten hasta olma olasılığı hakkında hangisi söylenebilir?', '%99 doğruluk, pozitifin %99 güvenilir olduğunu göstermez', ['Pozitif çıkan kişinin hasta olma olasılığı mutlaka %99\'dur', 'Pozitif çıkan kişi mutlaka sağlıklıdır', 'Hastalık oranı pozitif sonucun güvenilirliğini hiç etkilemez'], 'Hastalık nadir olduğunda, çok doğru bir test bile pozitiflerin çoğunu yanlış alarm olarak üretir. Pozitif öngörü değeri, doğruluktan farklı olarak hastalık oranına bağlıdır.'),
  ('Bir faaliyetin riski 5 mikromort (milyonda 5 ölüm olasılığı) olarak veriliyor. Bu faaliyetin tek seferlik ölüm olasılığı yüzde olarak kaçtır?', '%0,0005', ['%0,05, çünkü mikromort yüzde beşe eşittir', '%0,5', '%5'], '5 mikromort = 5 / 1.000.000 = 0,000005 = %0,0005\'tir. Mikromort, küçük ölüm risklerini karşılaştırmayı kolaylaştıran bir birimdir.'),
  ('Bir kişiye iki seçenek sunuluyor: kötü bir olayın riskini %5\'ten %0\'a indirmek ya da %50\'den %25\'e indirmek. Birçok kişi ilk seçeneği tercih ediyor. Bu eğilim hangi adla anılır?', 'Sıfır risk yanlılığı', ['Çıpalama', 'Kumarbaz yanılgısı', 'Texas keskin nişancı yanılgısı'], 'İkinci seçenek riski 25 puan, birincisi yalnızca 5 puan azaltır. İnsanlar, riski tamamen ortadan kaldırmaya orantısız bir değer biçer.'),
  ('Tversky ve Kahneman\'a göre insanlar çoğu zaman \'bir yazı-tura atışında yazı gelirse X lira kazan, tura gelirse 100 lira kaybet\' bahsini kabul etmek için X\'in yaklaşık 200 lira olmasını istiyor. Bu eğilim hangi kavramla açıklanır?', 'Kayıptan kaçınma', ['Büyük sayılar yasası', 'Kümelenme yanılsaması', 'Hayatta kalma yanlılığı'], 'Bahsin beklenen değeri X = 100 iken sıfırdır, ancak insanlar X ≈ 200 ister. Bu kayıptan kaçınma, kayıp ve kazancın psikolojik değerinin simetrik olmadığını gösterir.'),
  ('Bir sigorta şirketi poliçeler için, beklenen hasardan daha yüksek prim topluyor; yine de birçok kişi sigorta yaptırıyor. Bu davranış neden akla yatkındır?', 'Riskten kaçınma', ['Sigortanın beklenen değerinin pozitif olması', 'İnsanların olasılıkları hiç bilmemesi', 'Sigorta şirketinin hiç hasar ödememesi'], 'Beklenen değer ölçütüne göre sigorta kişiye ortalamada kayıptır; yine de felaket boyutundaki bir kayıptan korunmak, riskten kaçınan kişi için değerlidir.'),
  ('Bir hastalığın yaşam boyu görülme riski %1 olarak bildiriliyor. Bu bilgi, bir kişinin gelecek yıl hastalanma riskini nasıl bilgilendirir?', 'Yıllık risk çok daha düşüktür', ['Yıllık risk de %1\'dir', 'Yıllık risk %100\'dür', 'Yaşam boyu risk, yıllık riski hiçbir şekilde bilgilendirmez'], 'Yaşam boyu risk, onlarca yılın birikimidir; yıllık risk bu nedenle çok daha küçüktür. Zaman çerçevesi belirtilmeden verilen riskler yanlış yorumlanabilir.'),
  ('2016\'da yapılan bir inceleme, genetik makalelerinin yaklaşık beşte birinin ek dosyalarında gen adlarının (örneğin SEPT2) hesap çizelgesinde tarih olarak otomatik dönüştürüldüğünü buldu. Bu bulgu neyi gösterir?', 'Otomatik biçim dönüşümleri veriyi sessizce bozabilir', ['Genlerin ancak tarih olarak ölçülebildiğini', 'Elektronik tabloların hiçbir zaman kullanılmaması gerektiğini', 'Gen adlarının sayılarla gösterilemeyeceğini'], 'Hesap çizelgesi programları, metin gibi görünen girdileri sessizce tarihe çevirebilir. Veri aktarımlarında tür ve biçim kontrolü yapılmazsa hatalar analize sızar.'),
  ('Bir cerrah, başarı olasılığı %99 olan bir ameliyatı yapıyor; hasta, nadir bir komplikasyon nedeniyle ölüyor. Cerrahın kararı \'yanlıştı\' diyenler hangi hatayı yapıyor?', 'Kararı sonucuna göre yargılamak', ['Doğru sonuç çıkardıkları için hiçbir hata yok', 'Hastanın yaşını hiç hesaba katmıyorlar', 'Olasılıkları yüzde yerine kesirle ifade ediyorlar'], 'İyi bir karar kötü sonuçlanabilir; sonuç yanlılığı, kararın kalitesini yalnızca çıktıya bağlar. Karar, o anda mevcut kanıt ve olasılıklara göre değerlendirilmelidir.'),
  ('Bir proje için şimdiye dek 5 milyon lira harcanmış ve tamamlanması için ek 4 milyon lira gerekiyor; ancak tamamlandığında getirisi yalnızca 3 milyon lira olacak. \'Zaten çok harcadık, bırakamayız\' görüşü neden hatalıdır?', 'Batık maliyet karar dışında kalmalıdır', ['Geçmiş harcamalar her zaman gelecekteki getiriyi yükseltir', 'Proje tamamlanırsa batık maliyetin yine de geri dönmesi kesindir', 'Ek harcama hiçbir koşulda ölçülemez ve karar verilemez'], 'Ek 4 milyon liraya karşılık 3 milyon lira getiri, net 1 milyon liralık kayıptır. Batık maliyet, her iki seçenekte de aynı olduğu için karar dışında bırakılmalıdır.'),
  ('Ross, Lepper ve Hubbard\'ın 1975 deneyinde katılımcılara uydurma geri bildirimler verilip daha sonra bunların sahte olduğu açıklandı; ancak katılımcılar yine de önceki sahte bilgiye dayalı kanaatlerini koruyordu. Bu bulgu hangi eğilimi gösterir?', 'İnanç ısrarı; çürütülen kanıtın etkisi kalabilir', ['Çıpalama; ilk sayının etkisi sürer', 'Çerçeveleme; sunum biçimi tercihi belirler', 'Hayatta kalma yanlılığı; yalnız başarılar hatırlanır'], 'Bir kez oluşan nedensel açıklamalar, dayandığı kanıt çürütülse bile kendiliğinden ayakta kalabilir. Bu yüzden yanlış bilgiyi düzeltmek, ilk inancı silmeye her zaman yetmez.'),
  ('Bir kişi, çalışmayı fonlayan şirketten dolayı \'bu araştırmanın sonucu kesin yanlıştır\' diyor. Bu itiraz neden mantıksal olarak yetersizdir?', 'Finansman, yöntemin incelenmesinin yerini tutmaz', ['Finansman bilgisi bilimsel çalışmalarda hiç dikkate alınmaz', 'Fon sağlayanlar her zaman doğru sonuç elde eder', 'Yöntem ve veri hiçbir zaman incelenemez'], 'Çıkar çatışması dikkat gerektirir, ancak sonucun yanlış olduğunu tek başına kanıtlamaz. Doğru yaklaşım, yöntem ve verileri ayrıntılı incelemek ve bağımsız çalışmalarla karşılaştırmaktır.'),
  ('İki uzman, bir ilaçla ilgili çelişkili görüşler dile getiriyor; biri etkili, diğeri etkisiz diyor. Bir kişi, \'o hâlde doğrusu ortadadır, yarı etkili\' sonucuna varıyor. Bu çıkarım hangi hatayı yapıyor?', 'Orta yolu doğru saymak', ['Aşırı güven; kendi bilgisine fazla itimat etmek', 'Hayatta kalma yanlılığı; yalnız yaşayanları saymak', 'Anekdot; tek vakaya dayanmak'], 'Gerçek, iki uç görüşün ortasında olmak zorunda değildir. Kanıtın kalitesi ve miktarı değerlendirilmeden alınan \'ortalama\' görüş, yanlış olabilir.'),
  ('\'Bir ülkenin kişi başına gelir ortalaması yüksektir; o hâlde bu ülkenin her vatandaşı varlıklıdır.\' Bu önerme hangi yanılgıya örnektir?', 'Bölme yanılgısı; topluluk ölçüsünü bireye atfetmek', ['Birleşim yanılgısı; parçalardan bütüne geçmek, çünkü ortalama herkese uyar', 'Kumarbaz yanılgısı; art arda olayların bağımlılığı', 'Çıpalama; ilk rakamın etkisi'], 'Ortalama, gelir dağılımının eşitsizliğini gizler; çok zengin az sayıda kişi ortalamayı yükseltebilir. Topluluk özelliklerini bireylere uygulamak yanıltıcıdır.'),
  ('Bir tıp dergisi, yeni bir ilacın hastalık süresini \'ortalama 2 gün kısalttığını\' bildiriyor. Bir okuyucu \'ilacı kullanan her hastanın 2 gün kısaldığı\' sonucunu çıkarıyor. Bu çıkarımın hatası nedir?', 'Ortalama etki her bireyin etkisi değildir', ['Ortalama etkinin hiçbir zaman hesaplanamaması', 'Hastalık süresinin gün olarak ölçülememesi', 'Dergilerin ortalama kullanmaması'], 'Aynı ortalama, birkaç kişide büyük fayda ve çoğunda hiç fayda olmayan bir dağılımdan da çıkabilir. Bireysel etkiyi ortalamadan çıkarmak yanıltıcıdır.'),
  ('Bir araştırmada 20 kişilik grup A, \'çift kör olmayan\' bir müdahale alıyor ve katılımcılar ne aldıklarını biliyor. Sonuç öznel bir anket puanıdır. Bu tasarımın başlıca zayıflığı nedir?', 'Beklenti etkisi ayrıştırılamaz', ['Anketlerin hiçbir zaman sayısal olmaması', 'Grup sayısının sonsuz olması', 'Müdahalenin hiçbir zaman ölçülememesi'], 'Katılımcılar ne aldıklarını bildiğinde, öznel sonuçlar beklentilerden etkilenir. Körleme ve kontrol grubu bu yanlılığı azaltır.'),
  ('Bir şirket, müşteri memnuniyeti puanını yıllık ortalamayla değil, en iyi çeyreğin ortalamasıyla duyuruyor. Bu uygulama hakkında hangisi doğrudur?', 'Seçici dönem seçimi; durumu iyi gösterir', ['Yıllık ortalamayla aynı sonucu verir ve yanıltıcı değildir', 'Çeyrek ortalaması hiçbir zaman hesaplanamaz', 'Yalnızca sayısal olmayan veride yanıltıcıdır'], 'En iyi dönemi seçmek, ortalamanın kendisini yukarı çeker ve kötü dönemleri gizler. Dönem seçimi önceden belirlenmediğinde sonuç kiraz toplamaya dönüşür.'),
  ('Bir haber başlığı \'Bilim insanları kahvenin kansere yol açtığını keşfetti\' diyor; haberin içinde çalışmanın yalnızca 14 farede yapıldığı ve çok yüksek dozlar kullanıldığı yazıyor. Başlığı değerlendirirken en çok hangi sınırlılık dikkate alınmalıdır?', 'Hayvan ve yüksek doz çalışmasının insanlarda gerçek yaşam dozlarına doğrudan taşınamaması', ['Farelerin hiçbir zaman kahve içmemesi nedeniyle çalışmanın geçersiz olması, çünkü içme davranışı ölçülemez', 'Çalışmanın bir haber sitesinde yayımlanması nedeniyle hiç değer taşımaması', 'Kansere dair hiçbir çalışmanın fareyle yapılamaması'], 'Küçük örneklem ve yüksek dozlu hayvan deneyleri, insanlardaki olağan tüketim düzeyine kesin sonuç sağlamaz. Haber başlıkları genellikle bu sınırlılıkları gizler.'),
  ('Bir gazete, bir ilaç için \'klinik olarak kanıtlanmış\' ifadesini kullanıyor. Bu ifadenin tek başına yetersiz olmasının başlıca nedeni nedir?', 'Çalışmanın niteliği hakkında bilgi vermez', ['Klinik çalışmaların hiçbir zaman insanlarda yapılmaması', '\'Kanıtlanmış\' sözcüğünün Türkçede kullanılamaması', 'İlaçların hiçbir zaman etkisinin ölçülememesi'], 'Pazarlama dilindeki \'klinik olarak kanıtlanmış\' ifadesi, çalışmanın niteliği hakkında bilgi vermez. Küçük, kontrolsüz bir çalışma da bu etiketle anılabilir.'),
  ('Bir üniversite basın bülteni, gözlemsel bir çalışmayı \'X, Y\'yi önlüyor\' diye duyuruyor; makalenin kendi metni yalnızca \'X ile Y arasında ilişki bulunmuştur\' diyor. Bu durum haber kaynaklarında nasıl bir sorunu gösterir?', 'Bilimsel sonucun nedensellik diliyle abartılması', ['Bilimsel makalelerin sonuçlarını hiç yayımlamaması', 'Basın bültenlerinin hiçbir zaman doğru olmaması', 'İlişkinin hiçbir zaman bulunamaması'], 'Haber zincirinde ilişki dili sıklıkla nedensellik diline dönüşür. Güvenilir okuma için kaynak makalenin sonuç bölümüne ve çalışma türüne bakmak gerekir.'),
  ('Bir anket haberinde \'Gençlerin %60\'ı X\'e destek veriyor\' deniyor; metnin en altında anketin bir parti gençlik kolu tarafından yaptırıldığı yazılı. Bu bilgi okuyucuyu hangi yönde uyarmalıdır?', 'Yanlılık olabilir; bağımsız doğrulama gerekir', ['Anketin her durumda doğru olduğu yönünde', 'Anketin hiçbir zaman sayılmaması gerektiği yönünde', 'Gençlerin siyasetle ilgilenmediği yönünde'], 'Sponsorlu anketlerde örneklem ve soru kurgusu sonucu yönlendirebilir. Bu, sonucun yanlış olduğu anlamına gelmez; yöntem şeffaflığı ve bağımsız doğrulama gerekir.'),
  ('Bir çapraz çizelgede, grip aşısı olanların %70\'inin yaşlı olduğu görülüyor. Bir okuyucu \'yaşlıların %70\'i aşı oluyor\' sonucuna varıyor. Bu çıkarımın hatası nedir?', 'Koşullu oranlar farklıdır', ['Yüzde sayılarının toplamının 100 olmaması', 'Çizelgelerin hiçbir zaman okunamaması', 'Aşının yalnızca yaşlılarda etkili olması'], '\'Aşılıların %70\'i yaşlı\' P(yaşlı | aşılı) iken, \'yaşlıların %70\'i aşılı\' P(aşılı | yaşlı)\'dır. Satır ve sütun yüzdelerini karıştırmak yaygın bir veri okuma hatasıdır.'),
  ('Bir ülkede 1000 kişinin 400\'ü sigara içmektedir; sigara içenlerin 80\'i bir hastalığa yakalanmış, içmeyenlerin ise 60\'ı yakalanmıştır. Hastaların yüzde kaçı sigara içmektedir?', 'Yaklaşık %57', ['%20, çünkü oran sigara içenlerde hesaplanır', '%40', '%80'], 'Toplam hasta 80 + 60 = 140 kişidir; sigara içen hastalar 80 / 140 ≈ %57\'dir. Bu oran, sigara içenlerdeki hastalık oranı olan 80/400 = %20\'den farklı bir sorunun yanıtıdır.'),
  ('Bir sınıfta çok yüksek bir not ortalamasına sahip öğrencilerin büyük çoğunluğunun düzenli uyuyan öğrenciler olduğu görülüyor. Buradan \'düzenli uyuyan öğrencilerin çoğu yüksek not ortalamasına sahiptir\' sonucunu çıkarmak neden yanlıştır?', 'Koşullu oranlar farklıdır', ['Not ortalamaları ve uyku düzeni hiçbir zaman karşılaştırılamaz', 'Yüksek notluların sayısının her zaman düzenli uyuyanlardan fazla olması', 'Öğrencilerin tamamının düzenli uyuması'], 'İki koşullu oran, grupların büyüklüklerine bağlı olarak çok farklı olabilir. Örneğin yüksek notluların %90\'ı düzenli uyuyor olsa da düzenli uyuyanların yalnızca küçük bir bölümü yüksek notlu olabilir.'),
  ('Bir kafe sahibi, bir hafta boyunca günlük satışları ölçüyor ve cumartesi günü rekor satış görüyor; \'cumartesi her zaman en iyi gün\' diye bir politika belirliyor. Hangi ek veri bu çıkarımı sınamak için en gereklidir?', 'Birçok haftanın satışlarının karşılaştırılması', ['Aynı haftanın pazartesi satışlarının ortalaması', 'Kafedeki masa sayısı', 'Kafenin tabela rengi'], 'Tek bir haftalık gözlem, rastlantıyı eğilimden ayıramaz. Birçok hafta üzerinden gün etkisi ve değişkenlik değerlendirilmelidir.'),
  ('Bir araştırmanın özeti \'n = 12, 3 hafta, p = 0,04\' bilgisini veriyor. Bu bilgilere bakarak bulgunun güvenilirliği hakkında en uygun çıkarım hangisidir?', 'Küçük örneklem, kısa süre; sonuç ön bulgudur', ['p = 0,04 olduğundan sonuç kesin ve kalıcıdır', 'Üç hafta, her türlü etkiyi kesin olarak ölçmek için yeterlidir', 'Örneklem 12 kişi olduğunda güç hiçbir zaman sorun olmaz'], '12 kişilik ve 3 haftalık çalışmalar, düşük güç ve yüksek değişkenlik nedeniyle abartılmış etkiler bulabilir. Bu tür sonuçlar yeniden üretilmeden kesin sayılmamalıdır.'),
  ('Bir sosyal ağda kişilerin arkadaş sayısı farklıdır. Sosyolog Scott Feld\'in 1991\'de tanımladığı \'arkadaşlık paradoksu\' neyi söyler?', 'Ortalama olarak insanların arkadaşları, kendilerinden daha çok arkadaşa sahiptir', ['Ortalama olarak insanların arkadaşları, kendilerinden daha az arkadaşa sahiptir', 'Herkesin arkadaş sayısı ağdaki ortalamaya eşittir', 'Çok arkadaşlı kişilerin arkadaşları her zaman az arkadaşlıdır, çünkü kaynaklar sınırlıdır'], 'Çok arkadaşlı kişiler, başkalarının arkadaş listesinde daha sık yer alır; bu nedenle bir arkadaşı rastgele seçince çok bağlantılı birine denk gelme olasılığı artar. Yanlı örnekleme paradoksun kaynağıdır.'),
  ('Bir şehirde 10 ailenin her birinin 1 çocuğu, 10 ailenin her birinin 4 çocuğu var. Aile başına ortalama çocuk sayısı 2,5\'tir. Rastgele seçilen bir çocuğun ailesindeki ortalama çocuk sayısı kaçtır?', '3,4', ['2,5, çünkü aile ortalaması çocuklar için de geçerlidir', '1,0, çünkü tek çocuk en sık görülür', '4,0, çünkü her çocuk kalabalık ailede yaşar'], 'Toplam 50 çocuğun 40\'ı 4 çocuklu ailelerdedir: (10 × 1 + 40 × 4) / 50 = 3,4. Büyük ailelerdeki çocuklar örneklemde daha çok temsil edilir.'),
  ('Bir ligde takımların puan farkları arasındaki değişkenliğin bir bölümü gerçek beceri farklarından, bir bölümü ise maç sonuçlarındaki şanstan kaynaklanır. Şans payı artırılırsa lig tablosunun görünümü nasıl değişir?', 'Puan farkları küçülür; sıralama yeteneği daha az yansıtır', ['Takımlar arasındaki puan farkları büyür ve sıralama yeteneği daha çok yansıtır', 'Sıralama sabit kalır; çünkü şans yalnızca tek maçları etkiler', 'Bütün takımlar eşit puanda biter; çünkü şans herkese eşit dağılır'], 'Gözlenen sıralama değişkenliği = beceri değişkenliği + şans değişkenliği. Şans payı büyüdükçe sıralama becerinin güvenilir bir göstergesi olmaktan çıkar.'),
  ('Bir yatırım dergisi her yıl en iyi performans gösteren 10 fon yöneticisini ödüllendiriyor. Ödüllü yöneticilerin ertesi yıl performansının ortalamaya yaklaşması beklenir. Bu beklentinin temel nedeni nedir?', 'Başarı kısmen şanstır; şans payı tekrarlanmaz', ['Yöneticiler ödül aldıktan sonra çalışmayı bırakır', 'Fonların her yıl yeniden yapılandırılması', 'Ödül alan yöneticilerin diğerlerinden hep daha yaşlı olması'], 'Uç başarı, beceri ile şansın bileşiminden oluşur; şans bileşeni bağımsız olduğundan sonraki dönemde ortalamaya doğru geri döner. Ödül, bu etkiyi önlemez.'),
  ('Bir şehirde yalnız son 5 yıla ait 5 kasırga verisi bulunan bir dönem var ve sigorta şirketi bu 5 yıldan \'ortalama hasar\'ı hesaplayıp prim belirlemek istiyor. Hangi sınırlılık en önemlidir?', 'Kısa veri, nadir yıkıcı olayları içermeyebilir', ['Kasırgaların hiçbir zaman ölçülememesi', 'Hasarın yalnızca para birimiyle ifade edilemeyeceği', 'Beş yılın çok uzun bir veri olması'], 'Felaket olayları nadirdir ve kısa dönemli veride yer almayabilir; bu yüzden kısa örneklem riski hafife alır. Uzun dönem ve uç değer modelleme gerekir.'),
  ('Bir ülkenin geliri bir yılda %3 artarken nüfusu %2 artıyor. Kişi başına gelir yaklaşık kaç yüzde artmıştır?', 'Yaklaşık %1', ['Yaklaşık %5', 'Yaklaşık %3', 'Yaklaşık %1,5'], 'Kişi başına gelir yaklaşık 1,03 / 1,02 − 1 ≈ %1 artar. Toplam büyüme, nüfus artışına bölünmeden kişi başına refah artışı gibi yorumlanamaz.'),
  ('Bir ülkede ölüm sayısı, nüfusun yaşlanmasıyla iki yıl üst üste artıyor. Ölümlerin gerçekte daha \'tehlikeli\' bir döneme işaret edip etmediğini anlamak için hangi ayar yapılmalıdır?', 'Yaşa göre standardize oranı hesaplamalıdır', ['Yalnızca ölüm sayıları toplanmalıdır', 'Ölümler yaş gruplarına bölünmeden raporlanmalıdır', 'Yalnızca bir yıl ölçülmelidir'], 'Yaşlı nüfus arttıkça ham ölüm sayısı artar; yaş standardizasyonu bu yapısal etkiyi ayıklar. Ancak böyle bir oran, gerçek risk değişimini gösterebilir.'),
  ('Bir ankette tüm maddeler \'Katılıyorum\' yönünde yazılmıştır ve bazı katılımcılar içeriğe bakmadan çoğu maddeye \'katılıyorum\' diyor. Bu eğilimi azaltmak için en uygun düzenleme hangisidir?', 'Maddelerin bir kısmını ters (olumsuz) yönde yazmak', ['Bütün maddeleri daha uzun ve ayrıntılı yazmak, çünkü okuyucu daha dikkatli olur', 'Anketi yalnızca sabah saatlerinde uygulamak, çünkü yorgunluk azalır', 'Yanıt seçeneklerini ikiye indirip kararsızı kaldırmak'], 'Onaylama (evet deme) yanlılığı, içeriğe bakmadan katılma eğilimidir. Maddeleri olumlu ve olumsuz yönlerde dengelemek, bu eğilimi ortaya çıkarır ve etkisini azaltır.'),
  ('Bir ölçekte yanıtlayıcıların önemli bir bölümü yalnızca en uçtaki seçenekleri (\'kesinlikle katılıyorum\' ve \'kesinlikle katılmıyorum\') işaretliyor. Bu davranış puanlar arası karşılaştırmayı nasıl etkiler?', 'Puan farkları, tutumdan çok yanıt biçiminden kaynaklanabilir', ['Karşılaştırmayı daha güvenilir kılar, çünkü uç yanıtlar nettir', 'Karşılaştırmayı hiç etkilemez, çünkü seçenek sayısı sabittir', 'Karşılaştırmayı imkânsız kılar, çünkü ortalama hesaplanamaz'], 'Uç yanıt eğilimi, aynı tutuma sahip iki kişinin farklı puan almasına yol açabilir. Gruplar arası farklar yorumlanırken yanıt stili farkları göz önünde tutulmalıdır.'),
  ('Bir anketin \'Evlilik hayatınızdan memnun musunuz?\' sorusu, \'Genel olarak mutlu musunuz?\' sorusundan önce ya da sonra sorulduğunda genel mutluluk yanıtlarının değişmesi hangi etkiyle açıklanır?', 'Soru sırası etkisi; önceki soru sonrakini yönlendirir', ['Büyük sayılar yasası; örneklem büyüdükçe yanıtlar sabitlenir', 'Ekolojik yanılgı; grup bilgisi bireye uygulanır', 'Yanıtsızlık yanlılığı; bazı kişiler soruyu yanıtlamaz'], 'Önce sorulan soru, katılımcının dikkatini belirli bir alana çeker ve sonraki yargıyı çerçeveler. Karşılaştırma için soru sıraları sabit ya da rastgele sıralanmalıdır.'),
  ('Bir tarama programı, hızlı büyüyen kanserlere göre yavaş büyüyen kanserleri daha çok yakalıyor, çünkü yavaş olanlar tarama aralığında daha uzun süre saptanabilir durumda kalıyor. Bu yanlılığın adı nedir?', 'Süre yanlılığı', ['Hayatta kalma yanlılığı, yani yalnız yaşayanların analize girmesi', 'Öncül zaman yanlılığı', 'Yanıtsızlık yanlılığı'], 'Taramayla yakalanan vakalar, yavaş ilerleyen ve daha iyi seyirli olanlara doğru yanlıdır. Bu yüzden taramayla bulunan hastaların sağ kalımı, gerçek tarama yararından fazla görünür.'),
  ('Bir vaka-kontrol çalışmasında hastalığı olan kişiler, geçmişteki maruziyetleri sağlıklı kişilerden daha ayrıntılı ve daha çok hatırlıyor. Bu durum odds oranını nasıl etkiler?', 'İlişkiyi olduğundan güçlü gösterebilir', ['İlişkiyi olduğundan zayıf gösterir, çünkü hastalar maruziyeti unutur', 'Odds oranını her zaman 1\'e eşitler', 'Odds oranını hesaplanamaz kılar'], 'Hastalar nedenini araştırdığından maruziyeti daha çok hatırlar (hatırlama yanlılığı). Bu, vaka-kontrol çalışmalarında ilişkiyi abartma riskini doğurur.'),
  ('Bir araştırmacının makalesi, başka bir ekibin aynı kod ve aynı veri kümesiyle aynı sonuçları elde etmesini sağlıyor. Bu durum için doğru terim hangisidir?', 'Yeniden üretilebilirlik', ['Tekrarlanabilirlik (replikasyon) ile aynı yeni örneklemde sonuç bulma', 'Dışsal geçerlilik', 'Yayın yanlılığı'], 'Yeniden üretilebilirlik aynı veri ve analizle aynı sonucu bulmaktır; replikasyon ise yeni veriyle aynı bulguyu elde etmektir. İkisi birbirinden farklı güvenceler sunar.'),
  ('Bir meta-analiz, kalitesi çok düşük, yanlılığı yüksek 40 çalışmayı birleştirerek tek bir ortalama etki hesaplıyor. \'Çöp girerse çöp çıkar\' ilkesine göre bu sonuç hakkında ne söylenebilir?', 'Birleştirme çalışmaların yanlılığını gidermez', ['Çalışma sayısı fazla olduğundan sonuç kusursuzdur', 'Birleştirme her yanlılığı sıfırlar', 'Meta-analiz hiçbir zaman çalışmaların kalitesine bağlı değildir'], 'Meta-analiz, girdiği çalışmaların kalitesini aşamaz; ortak yanlılık, birleştirilince de sürer. Kalite değerlendirmesi ve duyarlılık analizi gereklidir.'),
  ('Bir araştırmada nüfus kayıtlarındaki yaşlara bakılınca 30, 40, 50 gibi yuvarlak yaşların beklenenden çok daha fazla bildirildiği görülüyor. Bu \'yaş yığılması\' (age heaping) neyin işaretidir?', 'Yaşların yuvarlanarak bildirildiği ölçüm hatasının', ['Nüfusun gerçekten yuvarlak yaşlarda doğmuş olmasının', 'Yaşların hiçbir zaman kayda geçmemesinin', 'Doğum tarihlerinin hep aynı ay olmasının'], 'Yaşını tam bilmeyenler yuvarlak sayıları tercih eder; bu da gerçek dağılımda görülmeyen yığılmalar yaratır. Veri kalitesi göstergesi olarak kullanılır.'),
  ('Kanada\'da hokey liglerinde yıl başında doğan çocukların elit takımlarda aşırı temsil edildiği görülüyor. Seçim yaş sınırı 1 Ocak olarak belirlendiğinden aynı yıl doğanların içinde yıl başı çocukları daha gelişmiş. Bu duruma ne ad verilir?', 'Göreli yaş etkisi', ['Hayatta kalma yanlılığı', 'Ortalama dönüş', 'Kümelenme yanılsaması'], 'Aynı yaş kategorisinde birkaç ay büyük olmak, fiziksel olarak avantaj sağlar ve seçmeleri etkiler; bu avantaj yıllarca birikerek yönlendirilir. Doğum ayı, yetenekle karışan bir karıştırıcıdır.'),
  ('Bir eğitim kampanyasının etkisini ölçmek için hedef kitleden gönüllülerin katılım öncesi ve sonrası puanları karşılaştırılıyor; ortalama puan 10 puan artıyor. Hangi ek tasarım öğesi, artışın kampanyadan kaynaklandığını en çok güçlendirir?', 'Rastgele dışarıda bırakılan bir karşılaştırma grubu', ['Katılımcı sayısını artırmak ve sonraki puanları kutlamak', 'Puanları daha sık ölçmek ve en iyi puanı raporlamak', 'Yalnızca kampanyayı tamamlayanları analiz etmek'], 'Rastgele ayrılmış bir karşılaştırma grubu, zamanın, öğrenme etkisinin ve ortalamaya dönüşün etkisini kampanya etkisinden ayırır.'),
  ('Vietnam Savaşı sırasında ABD\'de askere çağrılma sırası doğum gününe göre çekilen bir kurayla belirlendi. Bu uygulamayı ekonomistler neden askerlik etkisini ölçmek için \'doğal deney\' saydı?', 'Kura, askerlik riskini rastgele dağıttı', ['Askere çağrılanlar gönüllüydü, bu yüzden gruplar özdeşti', 'Kura yalnızca varlıklı ailelerin çocuklarını kapsadı ve tek bir toplumsal sınıfı temsil etti', 'Askerlik süresi herkes için farklıydı ve bu fark sonuçları açıkladı'], 'Doğum gününe dayalı kura, kişinin özelliklerinden bağımsız olduğundan, askere çağrılanlarla çağrılmayanlar ortalamada benzerdi. Rastgele benzeri atama nedensel çıkarım sağlar.'),
  ('Bir ilacın etkisi kadınlarda belirgin, erkeklerde yok denecek kadar azdır. \'İlacın ortalama etkisi küçüktür\' sonucu bireyler için neden yanıltıcı olabilir?', 'Ortalama etki, grup farklarını (etkileşimi) gizler', ['Ortalama etki hiçbir zaman hesaplanamadığı için', 'Kadınlar ile erkekler aynı ilaçla aynı sonucu aldığı için', 'İlaç etkisinin yalnızca doz miktarına bağlı olduğu için'], 'Etkileşim varsa tek bir ortalama etki, farklı alt gruplardaki zıt ya da farklı büyüklükteki etkileri örter. Alt grup düzeyinde etki incelemek gerekir.'),
  ('Bir araştırmada gelir sorusunu en çok yüksek gelirliler yanıtsız bırakıyor. Eksik gelir verilerini silip kalanlarla ortalama hesaplamak sonucu nasıl etkiler?', 'Gerçek ortalamanın altında kalır; eksiklik rastgele değildir', ['Gerçek ortalamanın üstünde kalır, çünkü yoksullar çok yanıtlar', 'Gerçek ortalamayla aynıdır, çünkü kalanlar yeterlidir', 'Hesaplanamaz hâle gelir, çünkü veri eksiktir'], 'Eksikliğin değere bağlı olması (rastgele olmayan eksiklik) kalan verileri yanlı kılar. Yüksek gelirliler dışarıda kaldığı için ortalama düşük çıkar.'),
  ('Eksik değerlerin her birini, o değişkenin gözlenen ortalamasıyla doldurmak veri kümesinin değişkenliği (varyansı) üzerinde ne etki yapar?', 'Varyansı olduğundan küçük gösterir', ['Varyansı olduğundan büyük gösterir', 'Varyansı hiç değiştirmez', 'Varyansı sıfır yapar ve bütün değerleri aynı kılar'], 'Ortalama ile doldurulan değerler ortalamadan sapma taşımadığı için toplam sapma azalır. Bu yöntem değişkenlik ve ilişkileri olduğundan zayıf gösterebilir.'),
  ('İki veri kümesi, müşteri numarasına göre birleştirilirken bazı müşterilerin ikinci veri kümesinde birden çok kaydı olduğu için sonuçtaki satır sayısı birinci veri kümesinden büyük çıkıyor. Bu durumdan ne çıkarılır?', 'Bu müşteriler sayımda çift sayılabilir', ['Birleştirme işlemi hatasızdır ve sayılar doğrudur', 'Müşteri sayısının sonsuz olması gerektiği', 'Satır sayısının her zaman azalması gerektiği'], 'Bire çok eşleşmeler, birleştirme sonrasında kayıt sayısını şişirir ve toplamları ya da ortalamaları bozabilir. Birleştirme sonrası satır sayısı mutlaka kontrol edilmelidir.'),
  ('Bir araştırmacı kayıtlı verilerde, rastgele seçilen 100 kayıttan 7\'sinin yanlış girildiğini fark ediyor. 5 milyon kayıtlık veri kümesi için bu bilgi neyi gösterir?', 'Yanlış oran %7 olabilir; temizlik gerekir', ['Tüm kayıtların doğru olduğu', 'Yanlış kayıtların yalnız örneklemde bulunduğu', 'Hiçbir temizlik yapılmaması gerektiği'], 'Örneklemdeki %7 oran, tüm veri hakkında bilgi verir (hata payıyla). Bu düzeydeki bir hata, sonuçları ciddi biçimde bozabilir.'),
  ('Bir şirket, müşteri memnuniyetini 1-5 arası ölçekle ölçüyor ve ortalama 4,2 çıkıyor. \'Müşterilerin %84\'ü memnun\' demek neden yanlıştır?', 'Puan ortalaması, memnun kişi oranı değildir', ['Ortalama puan her zaman memnun oranına eşittir', 'Müşteri sayısı hiçbir zaman bilinemez', 'Memnuniyet ölçülemez bir kavramdır'], '4,2 / 5 = %84, bir puan oranıdır; memnun müşterilerin oranı ise puan dağılımına bağlıdır. Bir ölçeğin puan ortalaması ile bir kişi oranı birbirine dönüştürülemez.'),
  ('Bir ankette \'son bir ayda spor yaptınız mı?\' sorusuna evet diyenlerin oranı bir yıl %30, ertesi yıl %45 çıkıyor; ancak ikinci yıl soru \'yürüyüş dahil\' ifadesiyle genişletilmiş. Bu artış için hangisi söylenebilir?', 'Artış, soru kapsamının değişiminden kaynaklanabilir', ['Artış kesin olarak gerçek bir davranış değişimini gösterir', 'Soru değişiklikleri sonucu hiçbir şekilde etkilemez', 'Yüzde artışları anketlerde hesaplanamaz'], 'Soru ifadesi ve kapsamı değiştiğinde yanıtlar gerçek davranış değişmese de değişir. Zaman karşılaştırması için sorunun aynı kalması gerekir.'),
  ('Bir salgında yalnızca test pozitif çıkan kişiler \'vaka\' sayılıyor. Vaka ölüm oranı (ölenler / doğrulanmış vakalar) ile enfeksiyon ölüm oranı (ölenler / tüm enfekte olanlar) arasında hangi ilişki beklenir?', 'Vaka ölüm oranı genellikle daha yüksektir', ['Vaka ölüm oranı genellikle daha düşüktür, çünkü doğrulanan vakalar hep hafif seyreder', 'İki oran, test sayısından bağımsız olarak her zaman eşittir', 'Vaka ölüm oranı hesaplanamaz, çünkü ölenler testle sayılmaz'], 'Hafif ya da belirtisiz enfeksiyonların çoğu test edilmediğinden paydadaki vaka sayısı gerçek enfekte sayısından küçüktür. Bu nedenle vaka ölüm oranı enfeksiyon ölüm oranını abartır.'),
  ('Bir ülkede test kapasitesi üç katına çıkarıldığında doğrulanmış vaka sayısı artarken vaka ölüm oranı düşüyor. Bu düşüşün en olası nedeni nedir?', 'Paydaya daha çok hafif vakanın girmesi', ['Tedavinin tek başına tüm hastalığı yok etmesi ve hiç ölüm kalmaması', 'Ölümlerin kayıt dışı bırakılması ve sayıların yarı yarıya düşmesi', 'Hastalığın virüsünün tamamen değişmesi ve zayıflaması'], 'Test sayısı arttıkça daha önce saptanamayan hafif vakalar da sayıma girer; pay aynı kalırken payda büyür ve oran düşer. Tek başına gerçek bir iyileşme göstermez.'),
  ('Bir ilacın yan etkisi için \'çok yaygın\' ifadesi, avrupa ilaç prospektüslerinde hangi sıklık düzeyini anlatır?', 'On kişide en az bir', ['Yüz kişide en az bir', 'Bin kişide en az bir', 'On bin kişide en az bir'], 'Prospektüs terimlerinde çok yaygın ≥1/10, yaygın 1/100-1/10, yaygın olmayan 1/1000-1/100, seyrek 1/10.000-1/1000\'dir. İnsanlar bu sözel ifadelerin sıklığını sıklıkla olduğundan fazla algılar.'),
  ('Bir ilaç kolesterolü belirgin biçimde düşürüyor; ancak kalp krizi ya da ölüm sayısında bir fark gösterilmemiş. Kolesterol bu çalışmada neyi temsil eder?', 'Yerine geçen (vekil) sonlanım noktası', ['Doğrudan klinik sonuç; ölümle aynı anlama gelir', 'Karıştırıcı değişken; her zaman ters yönde etki eder', 'Plasebo; ilacın etkisiz olduğunu gösterir'], 'Vekil sonlanım noktası (biyobelirteç), gerçek klinik sonuç olan ölüm ya da kalp krizinin yerine ölçülür. Biyobelirteçteki iyileşme, hastaya fayda sağlandığını garanti etmez.'),
  ('Bir ilacın laboratuvar ortamında kontrollü bir deneyle kanıtlanan etkisi (etkinlik) ile gerçek yaşamda geniş kitlelerde gözlenen etkisi (etkililik) neden farklı olabilir?', 'Uyum ve uygulama koşulları farklıdır', ['Gerçek yaşamda ilaçların hiç etkisinin ölçülememesi', 'Laboratuvarda yalnızca sağlıklı kişilerin bulunması', 'İlacın etkisinin yalnızca laboratuvarda sabit kalması'], 'Deneylerde seçilmiş ve izlenen hastalar, düzenli ilaç alım ve yakın takip vardır. Gerçek yaşamda bunların hiçbiri aynı düzeyde sağlanmayabilir.'),
  ('Bir ilaç yan etki bildirim sistemi, gönüllü bildirimlere dayanıyor ve haftalık bildirim sayısı bir haberden sonra aniden artıyor. Bildirim sayısındaki bu artış için en dikkatli yorum hangisidir?', 'Farkındalık bildirimi artırmış olabilir', ['Yan etki sıklığı kesin olarak artmıştır', 'Bildirimler hiçbir koşulda önemli değildir', 'Bildirim sistemleri yan etkileri tümüyle saptar'], 'Spontan bildirimler farkındalıktan etkilenir ve payda (kullanıcı sayısı) bilinmez. Bu sistemler sinyal üretir, ancak sıklık ve nedensellik için tek başına yeterli değildir.'),
  ('Bir aşı kampanyasında milyonlarca kişiye aşı yapılıyor. Aşıdan sonraki bir hafta içinde şansla bazı kişilerin kalp krizi geçirmesi beklenir; bu kişilerin kalp krizi aşıdan kaynaklanıyor mu sorusu için hangi bilgi gereklidir?', 'Beklenen arka plan kalp krizi oranı', ['Aşı şişesinin üretim tarihi', 'Kalp krizi geçiren kişilerin sayısı', 'Kampanyanın yapıldığı şehirdeki hava sıcaklığı'], 'Çok kalabalık bir grupta, aşıdan bağımsız olarak da yüksek sayıda kalp krizi görülür. Nedensellik için gözlenen sayı, aynı dönemde beklenen arka plan oranıyla karşılaştırılmalıdır.'),
  ('Bir tarama testi çok duyarlıdır (hastaların %99\'unu saptar). Bu testin \'negatif\' sonuç verdiği bir kişi için hangisi söylenebilir?', 'Negatif sonuç hastalığı büyük ölçüde dışlar', ['Negatif sonuç hastalığın olmadığını kesin garanti eder', 'Negatif sonuç hastalığın olduğunu gösterir', 'Negatif sonuç hiçbir bilgi taşımaz'], 'Yüksek duyarlılık, hastaların çoğunu yakalar; bu nedenle negatif sonuç hastalığı dışlamada güçlüdür. Yine de çok küçük bir yanlış negatif payı kalır.'),
  ('Bir kanser taramasında yanlış pozitif sonuç alan kişiler ek tetkik, biyopsi ve kaygı yaşıyor. Tarama programının yararı değerlendirilirken bu durum nasıl dikkate alınmalıdır?', 'Bir zarar olarak, kurtarılan yaşamlarla birlikte tartılmalıdır', ['Yok sayılmalı, çünkü yalnızca ölüm sayısı önemlidir', 'Yararın tek göstergesi sayılmalıdır', 'Yalnızca hastalığı olmayan kişileri ilgilendirir ve değerlendirmeye alınmaz'], 'Taramanın yararı ve zararı (yanlış alarmlar, aşırı tanı, gereksiz müdahaleler) birlikte değerlendirilmelidir. Bilinçli karar için iki tarafın da mutlak sayılarla sunulması gerekir.'),
  ('Bir araştırmada ilacın dozu arttıkça iyileşme oranı da düzenli biçimde artıyor. Bu \'doz-yanıt ilişkisi\' nedensellik açısından neyi gösterir?', 'Nedensel ilişkiyi destekler', ['Karıştırıcı olmadığını kesin kanıtlar', 'İlişkinin tesadüfi olduğunu gösterir', 'İlişkinin ters yönde olduğunu gösterir'], 'Bradford Hill ölçütlerinden biyolojik gradyan, nedensel ilişkiye destek olur. Ancak dozla birlikte artan bir karıştırıcı da benzer bir örüntü verebilir.'),
  ('Bir spor takımının fizyoterapisti, sakatlık sayısını azaltmak için yeni bir program uygulamaya başlıyor ve bir sezon sonra sakatlıkların azaldığını görüyor. En çok hangi açıklama, programın etkisinden önce düşünülmelidir?', 'Sakatlık sayısının ortalamaya dönmesi', ['Takımın kıyafet renklerinin değişmesi', 'Sakatlığın yalnızca program sayesinde olabilmesi', 'Maç sayısının hiçbir zaman değişmemesi'], 'Programa genellikle olağan dışı kötü bir sezondan sonra başlanır; bu durumda sakatlıkların ertesi yıl kendiliğinden azalması beklenir. Etki için karşılaştırma ya da çok sezonluk veri gerekir.'),
  ('Bir sonuçta \'hastaların %30\'u ilacı kullandıktan sonra yan etki bildirdi\' deniyor. Yan etki bildiren grupta bir kontrol grubu bulunmuyorsa yorum nasıl olmalıdır?', 'Yan etkinin kaynağı ayırt edilemez', ['Bütün yan etkiler ilaçtan kaynaklanıyordur', 'İlaç hiçbir yan etki yapmaz', 'Hastalık yan etki olarak sayılmaz'], 'Hastalığın belirtileri ya da başka etkenler de yan etki gibi bildirilebilir. Plasebo grubundaki yan etki bildirimi oranı, ilaca özgü etkiyi ayırt etmeye yarar.'),
  ('Bir çalışma, bir tedavinin etkisini ölçmek için hastaların semptom puanlarını tedaviden önce ve sonra kaydediyor; ancak hastalığın doğal seyri de zamanla iyileşmedir. Hangi tasarım etkiyi doğru ayırır?', 'Eşzamanlı bir kontrol grubu', ['Sadece tedavi grubunu daha uzun izlemek', 'Tedavi öncesi puanları iki kez ölçmek', 'Katılımcıların kendi yorumlarına güvenmek'], 'Eşzamanlı kontrol grubu, hem doğal iyileşmeyi hem ortalamaya dönüşü hem plasebo etkisini tedavi grubuyla aynı koşullarda gösterir.'),
  ('Bir fonun getirisi birinci yıl %100, ikinci yıl −%50 olmuştur. Fon yöneticisi \'ortalama yıllık getirimiz %25\' diyor. İki yılın sonunda yatırımcının parası ilk değerine göre nasıl değişmiştir?', 'Hiç değişmemiştir', ['%25 artmıştır, çünkü ortalama getiri %25\'tir', '%50 artmıştır, çünkü getiriler toplanır', '%25 azalmıştır, çünkü kayıp kazançtan ağırdır'], '100 TL, ilk yıl 200 TL olur, ikinci yıl 100 TL\'ye düşer. Aritmetik ortalama %25 gösterse de bileşik getiri %0\'dır; çarpımsal süreçlerde ortalama yanıltıcıdır.'),
  ('Bir ülkenin kişi başına geliri nominal dolarla A ülkesinde 40 bin, B ülkesinde 20 bin dolar; ancak B\'de fiyat düzeyi A\'nın yarısıdır. Satın alma gücü paritesine göre karşılaştırma için hangisi doğrudur?', 'İki ülkenin satın alma gücü eşittir', ['A\'nın geliri iki kat yüksektir, çünkü dolar sayısı iki katıdır', 'B\'nin geliri iki kat yüksektir, çünkü fiyatlar yarıdır', 'Karşılaştırma yapılamaz, çünkü ülkeler farklıdır'], 'Fiyat düzeyi yarı olunca 20 bin dolar, aynı sepetle 40 bin dolar kadar mal alır. Ülkeler arası karşılaştırmada nominal döviz kuru, yaşam maliyeti farkını göz ardı eder.'),
  ('Bir ülkede medyan hane geliri sabit kalırken ortalama hane geliri yükseliyor. Bu durumda gelirlerin dağılımı için ne söylenebilir?', 'Artış, en üst gelir diliminde yoğunlaşmıştır', ['Bütün hanelerin geliri eşit oranda artmıştır, çünkü bütün gelirler aynı oranda artar', 'Bütün hanelerin geliri azalmıştır', 'Gelir dağılımı hiç değişmemiştir'], 'Medyanı etkilemeyen ancak ortalamayı yükselten artış, üst uçtaki az sayıda yüksek gelirden gelir. Bu, eşitsizliğin arttığına işaret edebilir.'),
  ('Sports Illustrated dergisinin kapağına çıkan sporcuların performansının sonraki dönemde düşmesi \'kapak laneti\' diye anılır. Bu düşüş için istatistiksel açıklama hangisidir?', 'Zirvede seçilir; sonuç ortalamaya döner', ['Kapak fotoğrafı sporcunun yeteneğini doğrudan yok eder', 'Dergi sporcuları rastgele seçer ve bu seçim performansı etkiler', 'Kapakta olmayan sporcuların performansı hiç değişmez'], 'Sporcular, performansları olağanüstü yüksek olduğunda seçilir; bu uç performansın bir kısmı şanstır. Şans payı tekrarlanmadığından sonraki dönem ortalamaya yakın çıkar.'),
  ('Bir futbol liginde ev sahibi takımların galibiyet oranının deplasman takımlarından yüksek olması \'ev sahibi avantajı\' sayılıyor. Bu farkı yorumlarken hangi sorun gözden kaçırılmamalıdır?', 'Ev sahibi olma, takım gücünden ayrılmalı', ['Evde oynayan takımın her zaman daha iyi olduğu', 'Ev sahibi olmanın hiçbir etkisi bulunmadığı', 'Galibiyet oranlarının hiçbir zaman karşılaştırılamayacağı'], 'Fark; seyirci, saha, seyahat yorgunluğu gibi nedenlere bağlı olabilir. Karşılaştırma için aynı iki takımın hem evde hem deplasmanda oynadığı maçlara bakmak gerekir.'),
  ('Atletizmde dünya rekorlarının zaman içinde sık kırılması bazı yorumcularca \'insanlığın giderek hızlandığının\' kanıtı sayılıyor. Bu çıkarım için hangi etken de dikkate alınmalıdır?', 'Katılımcı sayısı ve teknolojinin değişmesi', ['Rekorların her yıl bilgisayarla rastgele üretilmesi', 'Atletlerin yalnızca ayakkabı rengine bağlı olarak koşması', 'Rekorların yalnız bir kez kırılabilmesi'], 'Yarışan sayısı arttıkça uç değerlerin görülme olasılığı da artar; teknik ve beslenme gelişmeleri de katkı yapar. Rekor sıklığı tek başına bir tek nedeni göstermez.'),
  ('Bir hisse fonunun geçmiş getirisi her yıl hisse piyasa ortalamasının üstünde kalmıştır ve fon, \'geçmiş getiri geleceğin garantisi değildir\' uyarısı yapıyor. Bu uyarının istatistiksel gerekçesi hangisidir?', 'Başarı kısmen şanstır', ['Geçmiş verinin hiçbir zaman ölçülememesi', 'Fonların her yıl yeniden kurulması', 'Yatırımcıların geçmişi hatırlamaması'], 'Üstün performansın bir kısmı şanstır ve şans tekrarlanmaz. Ayrıca geçmişte kalan fonlar seçilmiş başarılılardır.'),
  ('İstatistikte \'yanlılık\' (bias) terimi bir tahmin edicinin beklenen değeri ile gerçek parametre arasındaki sistematik fark için kullanılır. Bu tanımla gündelik dildeki \'taraflılık\' arasındaki fark nedir?', 'İstatistiksel yanlılık, niyetten bağımsız sistematik sapmadır', ['İstatistiksel yanlılık, her zaman bilinçli taraf tutmayı anlatır', 'İstatistiksel yanlılık yalnızca rastgele hataları içerir', 'İstatistiksel yanlılık yalnızca küçük örneklemlerde görülür'], 'Yanlılık, ölçümün ya da örneklemenin sistematik olarak bir yöne kaçmasıdır; araştırmacı iyi niyetli olsa da oluşabilir. Rastgele hata ise yöne sahip değildir ve tekrarlarda ortalamada sönümlenir.'),
  ('Bir köpekbalığı saldırısı çok tehlikelidir, ancak insanların köpekbalığı saldırısına uğrama olasılığı çok düşüktür. Risk analizi dilinde bu durumu en iyi hangi ayrım anlatır?', 'Tehlike büyük, risk (olasılık ve zarar birlikte) küçüktür', ['Tehlikenin küçük, riskin büyük olması', 'Tehlike ile riskin tamamen aynı kavram olması', 'Tehlikenin yalnızca denizde, riskin yalnızca karada anlam taşıması'], 'Tehlike, bir şeyin zarar verme gücüdür; risk ise zararın olasılığı ile büyüklüğünün birleşimidir. Çok tehlikeli bir olay, olasılığı çok düşükse düşük riskli olabilir.'),
  ('\'Bir ürün diğerinden üç kat daha az yağ içeriyor\' ifadesi istatistik okuryazarlığı açısından neden belirsizdir?', 'Kastedilen oran açıkça belirtilmez', ['Yağ miktarının hiçbir zaman ölçülememesi', 'Üç sayısının her zaman yanlış olması', 'Yağ içeriğinin yalnız ürün ağırlığına bağlı olması'], 'Üç kat daha az; üçte biri mi, yoksa üçte ikisi daha az mı demektir? Açık ve yoruma kapalı ifade için gerçek miktarlar ya da yüzdeler verilmelidir.'),
  ('Bir araştırma \'iki değişken arasında korelasyon yoktur\' sonucuna varıyor. Bu ifade teknik olarak neyi kapsar ve neyi kapsamaz?', 'Doğrusal ilişkinin yokluğunu', ['Her türlü ilişkinin yokluğunu; hiçbir bağıntı olamaz', 'Yalnızca nedensel ilişkinin yokluğunu; doğrusal ilişki olabilir', 'İki değişkenin ölçülemediğini; veri toplanamamıştır'], 'Pearson korelasyonu doğrusal ilişkiyi ölçer; örneğin ters U biçimli bir ilişkide korelasyon sıfıra yakın çıkabilir. Korelasyonun sıfır olması, bağımsızlık anlamına gelmez.'),
  ('Yeni açılan bir mağazada \'müşterilerin ortalama %40\'ı memnun\' deniyor. Bu ifadede \'ortalama yüzde\' neden belirsizdir?', 'Hangi ortalama ve ağırlık belirsizdir', ['Yüzdelerin hiçbir zaman ortalaması alınamaz', 'Memnuniyet yüzde ile ifade edilemez', 'Müşteri sayısı hiçbir zaman bilinemez'], 'Şubelerin ortalama yüzdesi ile tüm müşteriler üzerinden yüzde, farklı sayılar verebilir. Yüzdelerin ortalaması alınırken grup büyüklükleri dikkate alınmalıdır.'),
  ('Bir sınıfta öğretmen, sınav notlarını hem \'ortalama 60\' hem \'medyan 75\' olarak açıklıyor. Bu iki ölçünün farklı olması, notların dağılımı hakkında ne düşündürür?', 'Çok düşük birkaç not ortalamayı aşağı çekmiştir; dağılım sola çarpıktır', ['Çok yüksek birkaç not ortalamayı yukarı çekmiştir; dağılım sağa çarpıktır', 'Notlar tam simetrik dağılmıştır', 'Notlar ortalamadan yüksek değildir'], 'Ortalama medyandan küçükse, düşük uç değerler ortalamayı çekiyor demektir. Bu durum sola çarpık bir dağılıma işaret eder.'),
  ('Bir bahis ilanında bir sonucun gerçekleşme şansı \'3\'e 1\' (3:1, lehine) olarak belirtiliyor. Bu odds ifadesi olasılık olarak neye karşılık gelir?', '%75', ['%33, çünkü üç ile bir arasındaki oran alınır', '%25, çünkü bir parça lehine ayrılır ve diğerleri aleyhinedir', '%50, çünkü iki sonuç vardır'], '3:1 lehine odds, 3 başarı karşısında 1 başarısızlık demektir; olasılık 3 / (3 + 1) = %75\'tir. Odds ile olasılık farklı ölçeklerdir ve karıştırılmamalıdır.'),
  ('Bir işlem 100 bağımsız adımdan oluşuyor ve her adım %99 olasılıkla hatasız tamamlanıyor. Bütün işlemin hatasız tamamlanma olasılığı yaklaşık kaçtır?', 'Yaklaşık %37', ['Yaklaşık %99, çünkü her adım yüksek güvenilirlikte', 'Yaklaşık %90, çünkü hatalar birbirini dengeler', 'Yaklaşık %1, çünkü adım sayısı çoktur'], '0,99^100 ≈ 0,366\'dır. Çok sayıda yüksek olasılıklı adımın bileşimi, toplam başarı olasılığını belirgin biçimde düşürür.'),
  ('Bir tahminci, olasılık tahminlerini hiç %0 ya da %100 vermeyerek her zaman %50 ile %90 arasında bildiriyor. Çok sayıda tahmin sonrası kalibrasyonu değerlendirilirken hangi gözlem \'iyi kalibre\' demektir?', '%80 dediği olayların yaklaşık %80\'inin gerçekleşmesi', ['%80 dediği olayların tamamının gerçekleşmesi', '%80 dediği olayların yarısının gerçekleşmesi', '%80 dediği olayların neredeyse tamamının gerçekleşmemesi'], 'İyi kalibrasyon, bildirilen olasılıklarla uzun vadeli gerçekleşme sıklıklarının uyumudur. Hepsinin gerçekleşmesi aşırı ihtiyatlı, yarısının gerçekleşmesi ise aşırı güvenli olduğunu gösterir.'),
  ('Bir depremin büyüklüğü 6,0\'dan 8,0\'a çıkıyor. Richter benzeri logaritmik büyüklük ölçeğine göre genlikteki ve yaklaşık enerjideki artış kaç katıdır?', 'Genlik 100 kat, enerji yaklaşık 1000 kat', ['Genlik 2 kat, enerji yaklaşık 4 kat, çünkü enerji de aynı oranda artar', 'Genlik 10 kat, enerji yaklaşık 100 kat', 'Genlik 100 kat, enerji yaklaşık 100 kat'], 'Her bir büyüklük birimi genliği 10 kat artırır; iki birim 10² = 100 kattır. Enerji ise birim başına yaklaşık 31,6 kat artar; 31,6² ≈ 1000.'),
  ('Tennessee\'de 1980\'lerde yapılan STAR çalışmasında öğrenciler küçük ve büyük sınıflara rastgele atandı. Bu tasarımın, \'küçük sınıflarda başarı daha yüksek\' şeklindeki gözlemsel bulgulara göre üstünlüğü nedir?', 'Karıştırıcılar dengelendi', ['Öğrenci sayısının çok daha fazla olması', 'Sınıf büyüklüğünün hiç ölçülmemesi', 'Tüm öğretmenlerin aynı olması'], 'Gözlemsel verilerde zengin ya da başarılı okullar küçük sınıf sunabilir. Rastgele atama, sınıf büyüklüğü dışındaki farkları ortalamada eşitleyerek nedensel çıkarım sağlar.'),
  ('İki ülkenin okuma puanları 502 ve 500\'dür ve her puanın standart hatası yaklaşık 3\'tür. Bu iki ülkenin sıralamasını yorumlarken en doğru ifade hangisidir?', '2 puanlık fark belirsizlik içinde kalır', ['502 olan ülke kesin olarak daha başarılıdır', 'Fark, ölçüm hatasından büyüktür', 'Puanlar farklı olduğundan kıyaslanamaz'], 'Standart hata yaklaşık 3 iken 2 puanlık fark şansla kolayca ortaya çıkar. Sıralamalar, belirsizlik aralıklarıyla birlikte yorumlanmalıdır.'),
  ('Bir lise \'mezunlarımızın %99\'u üniversiteye yerleşti\' diyor; okul her yıl başarısız görünen öğrencileri bir alt sınıfta dönem sonunda başka okullara yönlendiriyor. Başarı oranının bu şekilde yüksek çıkması hangi sorundan kaynaklanır?', 'Zayıflar elenmiş; oran yapay yükselir', ['Okulun öğrenci sayısının çok az olması', 'Mezuniyet oranlarının yüzde olarak ölçülememesi', 'Üniversite yerleştirme sisteminin hiç ölçülmemesi'], 'Okul, başarı oranını paydadan zayıf öğrencileri çıkararak yükseltiyor. Başarı, gelen tüm öğrenciler üzerinden hesaplanmadığında yanıltıcıdır.'),
  ('Bir okulun ham sınav ortalaması yüksektir ancak okul, zaten çok başarılı öğrencileri kabul eden bir okuldur. Okulun \'eğitim kalitesini\' ölçmek için hangi gösterge daha uygundur?', 'Girişe göre ilerleme', ['Yalnızca son sınavdaki ham ortalama', 'Yalnızca öğrenci sayısı', 'Yalnızca öğretmen sayısı'], 'Ham puan, kabul edilen öğrencilerin başlangıç düzeyini de yansıtır. Katma değer, öğrenci başlangıcı sabitleyerek okulun etkisini ayırmaya çalışır.'),
  ('Bir şehirde yıllık ortalama sıcaklık 30 yıl boyunca yılda 0,03 °C artıyor, ancak yıllık değişkenlik ±0,8 °C. Bir kişi son iki yılın 0,2 °C düşüşünden \'eğilim sona erdi\' sonucunu çıkarıyor. Bu çıkarım için hangisi doğrudur?', 'İki yıllık değişim dalgalanma içinde kalır', ['İki yıl eğilimi her zaman tersine çevirir', 'Yıllık dalgalanma eğilimi hesaplanamaz kılar', 'Eğilimler yalnız iki yıllık verilerle belirlenir'], 'Yıllık dalgalanma (±0,8), kısa dönemli değişimden çok daha büyüktür. Eğilimleri değerlendirirken uzun seriler ve dalgalanmaya göre yorum gerekir.'),
  ('Bir araştırma, emniyet kemeri takanların takmayanlardan daha az ölümcül kaza geçirdiğini gösteriyor. Kemer takanların genel olarak daha dikkatli sürücüler olabileceği düşünülürse, bu karşılaştırmada hangi sorun vardır?', 'Dikkat hem kemeri hem riski etkiler', ['Kemer takanların sayısının çok az olması', 'Kazaların hiçbir zaman kayda geçmemesi', 'Kemer kullanımının ölçülememesi'], 'Dikkatli sürücüler hem kemer takar hem daha az kaza yapar; bu yüzden gözlenen fark kısmen kemerden bağımsız olabilir. Karşılaştırma için sürücü özellikleri kontrol edilmelidir.'),
  ('Bir okul bölgesinde 50 yıldır kayıtlı öğrenci sayıları verisinde okul kayıt kuralı değiştiğinde grafik birden sıçrıyor. Bu sıçrama için en dikkatli yorum hangisidir?', 'Kayıt kuralı farkından kaynaklanabilir', ['Sıçrama her zaman gerçek bir nüfus patlamasıdır', 'Kayıt kuralları hiçbir zaman sayıları etkilemez', 'Sıçrama yalnız yuvarlamadan kaynaklanır'], 'Ölçüm ya da kayıt kuralı değiştiğinde serilerde yapay kırılmalar oluşur. Gerçek bir değişim için kuralın sabit olduğu dönemler karşılaştırılmalıdır.'),
  ('Bir araştırmacı, düşük gelirli ailelerin çocuklarının sınav puanının, yüksek gelirlilerden daha düşük olduğunu görüyor ve sonuç olarak \'gelir puanı belirler\' diyor. Hangi alternatif açıklama dışlanmalıdır?', 'Okul kalitesi ve aile eğitimi', ['Sınavın hiç yapılmamış olması', 'Çocukların yalnızca yaş farkı', 'Gelir ölçümünün sayı olmaması'], 'Gelir; okul kalitesi, kaynaklar ve aile eğitim düzeyi gibi birçok etkenle birlikte değişir. Gelirin tek başına nedensel payı, bu karıştırıcılar kontrol edilmeden ayrıştırılamaz.'),
  ('1986\'da Challenger uzay mekiğinin fırlatılması öncesinde mühendisler, yalnızca O-halka hasarı görülen önceki fırlatmaların sıcaklıklarını incelemiş, hasarsız 17 fırlatmayı analize katmamıştı. Bu veri seçimi hangi sorunu doğurdu?', 'Tüm fırlatmalara bakılmayınca ilişki gizlendi', ['Mekiğin sıcaklığa hiç duyarlı olmadığı kanıtlandı', 'Analiz, hasarsız fırlatmaları fazla ağırlıklandırdı', 'Veri tamamen rastgele toplandığı için güvenilirdi'], 'Yalnızca sonucu (hasarı) gösteren olaylara bakmak, sonuç olmayan olayları gizler. Tüm fırlatmalar incelendiğinde soğuk havada hasar riski belirgin biçimde yüksekti.'),
  ('1906\'da Francis Galton, bir fuarda 787 kişinin bir öküzün ağırlığını tahmin ettiği yarışmanın sonuçlarını inceledi; tahminlerin ortancası gerçek değerden %1\'den az saptı. Bu bulgu \'kalabalığın bilgeliği\' için ne gösterir?', 'Bağımsız hatalar birbirini götürebilir', ['Tek bir uzmanın tahmini her zaman yanlıştır', 'Kalabalık büyüdükçe tahminler hep sapar', 'Ortanca hiçbir zaman gerçeğe yaklaşamaz'], 'Bağımsız ve yanlı olmayan hatalar bir araya gelince birbirini götürür ve ortalama ya da medyan gerçeğe yaklaşır. Hatalar ortak bir yönde sapıyorsa bu etki çalışmaz.'),
  ('1954 Salk çocuk felci aşısı saha denemelerinin bir bölümünde, ailelerin izniyle ikinci sınıf öğrencileri aşılanırken birinci ve üçüncü sınıflar kontrol sayıldı. Bu tasarım hangi sorun nedeniyle eleştirildi?', 'Gruplar rastgele atanmamıştı', ['Çocukların hastalanmaması', 'Aşı dozunun ölçülememesi', 'Denemenin yalnız bir ilde yapılması'], 'Aile izni, gelir ve hijyen gibi hastalığı etkileyen özelliklerle ilişkiliydi. Bu yüzden rastgele ve plasebolu tasarım, nedensel çıkarım için daha güvenilirdi.'),
  ('Ellen Langer\'in 1975 deneyinde piyango biletini kendisi seçen katılımcılar, rastgele verilen bilete göre bileti satmak için çok daha yüksek fiyat istedi. Bu davranış hangi eğilimi gösterir?', 'Kontrol yanılsaması; seçimin etkilediğine inanmak', ['Kayıptan kaçınma; satmanın bir kayıp olduğunu hissetmek', 'Çıpalama; ilk teklife bağlanmak', 'Savcı yanılgısı; koşullu olasılıkları ters çevirmek'], 'Şansa dayalı bir sonuçta kendi seçimi, kişinin kontrol hissini artırır; bilet değeri gerçekte aynıdır. Bu yanılsama, kumar davranışında rol oynar.'),
  ('Bir gazete \'Bu yıl hiç trafik kazası yaşamayan 10 sürücüyle röportaj yaptık; hepsi sabah kahvesi içiyor\' diyor ve \'sabah kahvesi kazayı önler\' sonucuna varıyor. Bu çıkarımdaki temel eksiklik nedir?', 'Kahve alışkanlığı bilinmiyor', ['Kahvenin hiçbir zaman içilememesi', 'Sürücü sayısının fazla olması', 'Kaza sayısının hiç hesaplanamaması'], 'Yalnızca sonucu olumlu olanların ortak özelliğine bakmak, aynı özelliğin kaza yapanlarda da olup olmadığını bilmeden anlamsızdır. Karşılaştırma grubu eksiktir.'),
  ('Whickham\'da (İngiltere) 20 yıllık bir izlemede sigara içen kadınların %76\'sı, içmeyenlerin ise %69\'u hayatta kaldı. Yaş gruplarına ayrıldığında içenlerin hayatta kalma oranı çoğu yaşta daha düşüktü. Toplamdaki bu tersliğin nedeni nedir?', 'Sigara içenler daha gençti', ['Sigara içmenin yaşamı kesin olarak uzatması', 'Kadınların hiç ölmemesi', 'Sigaranın etkisinin hiç ölçülmemesi'], 'İçmeyen kadınlar ortalamada daha yaşlıydı ve yaşlılar zaten daha çok öldü. Yaş, karıştırıcı olarak toplam karşılaştırmanın yönünü ters çevirdi.'),
  ('Bir şirketin aylık satışları her ay %2 artıyor. Bir yıl sonunda satışlardaki toplam artış yaklaşık kaçtır?', 'Yaklaşık %27', ['Yaklaşık %24, çünkü aylık artışlar 12 ile çarpılır', 'Yaklaşık %20, çünkü yıl on ay sayılır', 'Yaklaşık %2, çünkü oran her ay aynıdır'], '1,02^12 ≈ 1,268\'dir; yıllık artış yaklaşık %26,8\'dir. Aylık oranları toplamak (%24), bileşik etkiyi göz ardı eder.'),
  ('Bir şirketin haftalık satışları art arda 4 hafta boyunca her hafta %5 düşüyor. Dört haftalık toplam düşüş yaklaşık kaçtır?', 'Yaklaşık %18,5', ['Tam olarak %20, çünkü düşüşler toplanır', 'Yaklaşık %5, çünkü oran sabittir', 'Yaklaşık %25, çünkü dört hafta bir çeyrektir'], '0,95^4 ≈ 0,8145\'tir; yani %18,5\'lik düşüş. Ardışık yüzde azalışlar toplanmaz, çarpılır; toplam kayıp doğrudan toplamdan küçüktür.'),
  ('Bir ürünün maliyeti 100 TL, satış fiyatı 120 TL\'dir. Kâr, maliyet üzerinden %20 olarak ifade edilirken satış fiyatı üzerinden kâr marjı yaklaşık kaçtır?', 'Yaklaşık %16,7', ['%20, çünkü kâr tutarı aynıdır', '%24, çünkü marj maliyetin 1,2 katıdır', '%12, çünkü satışın yüzde 10\'u eklenir'], 'Kâr tutarı 20 TL\'dir; maliyete göre %20, satışa göre 20/120 ≈ %16,7\'dir. Aynı kâr, farklı tabana göre farklı yüzdelerle ifade edilir.'),
  ('Bir firmanın A ürününün satışı %20, B ürününün satışı %30 artmıştır. Toplam satışın %25 artmış olması hangi koşulda doğru olur?', 'Önceki satışlar eşit olduğunda', ['Her zaman, çünkü ortalama doğrudan alınır', 'Yalnızca B ürününün satışı fazlaysa', 'Hiçbir koşulda doğru olmaz'], 'Toplam artış, ürünlerin eski satış paylarıyla ağırlıklandırılmış ortalamadır. Basit ortalama yalnızca satış tutarları eşitse geçerlidir.'),
  ('Bir kişi \'yüzde 5 faizle 20 yıl sonra paramın iki katından fazlasına sahip olurum\' diyor. Bileşik faizle 20 yıl sonra para yaklaşık kaç katına çıkar?', 'Yaklaşık 2,65 katına', ['Yaklaşık 2 katına, çünkü faiz hep basittir', 'Yaklaşık 1,5 katına', 'Yaklaşık 5 katına'], '1,05^20 ≈ 2,65\'tir. Basit faizle ise 1 + 20 × 0,05 = 2 kat olurdu; fark bileşik etkiden gelir.'),
  ('Bir sağlık bakanlığı, ölüm oranı en yüksek 5 hastaneye kalite geliştirme programı uyguluyor ve ertesi yıl bu hastanelerin ortalama ölüm oranı düşüyor. Programın etkisini ayırt etmek için en uygun tasarım hangisidir?', 'Benzer ama programsız hastanelerle karşılaştırmak', ['Yalnızca programa alınan hastaneleri ilk ve ikinci yıl karşılaştırmak', 'Ölüm oranını yüzdeyle değil sayıyla izlemek', 'Hastanelerin hasta sayısını azaltmak'], 'Seçilen hastaneler uçta olduğundan, program olmasa da ortalamaya yaklaşırlardı. Programsız benzer hastaneler, bu beklenen yaklaşmayı gösteren kontrol sağlar.'),
  ('Bir şirket, satış performansı en düşük %10\'luk dilimdeki satış temsilcilerine koçluk veriyor ve bir sonraki çeyrekte performans artıyor. Koçluk etkisini abartma riski neden vardır?', 'Uç düşüş kısmen şanssızlıktı', ['Koçluk performansı hiçbir zaman etkileyemez', 'Satış performansının hiç ölçülememesi', 'Tüm temsilcilerin her çeyrek aynı performansı göstermesi'], 'Düşük dilim seçilirken geçici düşüşler de dahil olur. Rastgele atanmış bir kontrol grubu olmadan, artışın ne kadarının koçluktan geldiği bilinemez.'),
  ('Bir kumarhane, ABD tipi rulette (38 gözlü) tek bir sayıya yapılan 1 liralık bahse 35 lira ödüyor (kazanana 35 kâr). Uzun vadede kumarhanenin bahis başına beklenen kârı yaklaşık kaçtır?', 'Yaklaşık %5,26', ['Yaklaşık %2,6, çünkü oran ikiye bölünür', 'Yaklaşık %35', 'Yaklaşık %0,5'], 'Beklenen değer (1/38) × 35 + (37/38) × (−1) = −2/38 ≈ −%5,26\'dır; oyuncunun kaybı kumarhanenin kazancıdır. Büyük sayılar yasası sayesinde bu avantaj çok sayıda bahiste gerçekleşir.'),
  ('Küçük bir sigorta şirketi 10 sigortalıyla, büyük bir şirket 10.000 sigortalıyla çalışıyor ve her sigortalının yıllık hasar riski bağımsız ve aynıdır. Hangi şirketin kişi başına ortalama hasarı yıldan yıla daha az dalgalanır?', 'Büyük şirket; ortalamanın değişkenliği 1/√n ile azalır', ['Küçük şirket; çünkü çalıştığı kişi sayısı az olduğundan hasarlar dengelenir', 'İkisi de eşit; çünkü her sigortalının riski aynıdır', 'Hiçbir şirket; çünkü hasarlar bağımsız olduğunda dalgalanma artar'], 'Bağımsız risklerin ortalamasının standart sapması √n ile azalır. Sigortacılığın temeli, çok sayıda riskin havuzlanmasıdır.'),
  ('Bir veri analisti, kişilerin sağlık verisini veri setinde yalnızca ad ve soyadını silerek yayımlıyor; doğum tarihi, posta kodu ve nadir bir hastalık kaydı yerinde bırakılıyor. Bu paylaşımın en büyük riski nedir?', 'Yeniden kimliklendirme', ['Verinin fazla büyük olması', 'Hastalık adlarının Türkçe olmaması', 'Doğum tarihlerinin sayı içermesi'], 'Ad silmek tek başına anonimlik sağlamaz; nadir özellik birleşimleri bireyleri ayırt eder. Genelleme ve küçük hücre bastırma gerekir.'),
  ('Bir ülkede doğumda yaşam beklentisi 78 yıl olarak veriliyor. 65 yaşına ulaşmış bir kişinin beklenen toplam yaşam süresi için ne söylenebilir?', '78\'den yüksektir; erken ölümler atlatılmıştır', ['78\'e eşittir; çünkü yaşam beklentisi herkes için aynıdır', '78\'den düşüktür; çünkü kişi zaten yaşlanmıştır', 'Hesaplanamaz; çünkü yaş verilmemiştir'], 'Doğumda yaşam beklentisi, erken yaşlarda ölenleri de içerir. 65 yaşına ulaşanlar bu erken ölüm riskini atlatmıştır; dolayısıyla beklenen toplam ömürleri ortalamanın üstündedir.'),
  ('Bir reklam, ürünü \'bölgesinin en hızlı büyüyen markası\' olarak tanıtıyor. Bu iddia en çok hangi veri okuma tekniğine dayanıyor olabilir?', 'Kategoriyi daraltmaya', ['Örneklem büyüklüğünü sonsuza çıkarmaya', 'Kategorileri hiç tanımlamamaya', 'Verilerin hiçbir zaman toplanmamasına'], '\'En iyi\' iddiaları, kategori yeterince daraltıldığında hemen her ürün için doğru yapılabilir. Karşılaştırma grubu ve dönem açıkça belirtilmelidir.'),
  ('Bir haber, \'Trafik kazalarının %70\'i alkolsüz sürücülerce yapılıyor, o hâlde alkol kullanımı kazalarda belirleyici değildir\' diyor. Bu çıkarımın temel hatası nedir?', 'Taban oranı göz ardı edilmiştir', ['Kazaların sayısının hiçbir zaman sayılamaması', 'Alkolün her zaman kazayı önlemesi', 'Yüzdelerin hiçbir zaman toplanamaması'], 'Sürücülerin büyük çoğunluğu alkolsüzdür; bu yüzden kazaların çoğu onlardan gelir. Sürücü başına kaza riski, alkollü sürücülerde belirgin biçimde daha yüksek olabilir.'),
  ('Bir ülkede işsiz sayısı sabit kalırken çalışan sayısı artıyor. \'İşsizlik oranı\' ile \'istihdam oranı\'nın seyri hakkında hangisi söylenebilir?', 'İşsizlik oranı düşer, istihdam oranı artar', ['İşsizlik oranı artar, istihdam oranı azalır', 'İkisi de değişmez', 'İşsizlik oranı artar, istihdam oranı da artar'], 'İşsizlik oranı işsiz / işgücü, istihdam oranı çalışan / nüfustur. Çalışan sayısı arttıkça işgücü büyür ve işsizlik oranı düşer, istihdam oranı artar.'),
  ('Bir hastalığın tedavisinde yeni ilaç grubundaki hastaların ortalama yaşam süresi 8,2 yıl, kontrol grubunun 8,0 yıldır; fark istatistiksel olarak anlamlı çıkmıştır. Bu bulgu için hangisi söylenebilir?', 'Anlamlı ama yaklaşık 2,4 aylık kazanç', ['Fark anlamlı olduğu için ilaç hayat kurtarıcıdır', 'Fark küçük olduğu için sonuç tesadüftür', 'Fark yok sayılmalıdır, çünkü yıl ölçülemez'], '0,2 yıl yaklaşık 2,4 aydır. Büyük örneklemde küçük farklar da anlamlı olur; klinik önem, farkın büyüklüğüne ve hastanın değerlerine bağlıdır.'),
  ('Bir kişi, gelirleri yıllardır artan bir ülkede \'herkesin durumu iyileşti\' diyor; medyan gelir sabit, ortalama gelir artıyor. Hangi ek veri bu iddiayı değerlendirmek için en yararlıdır?', 'Gelir dilimlerine göre değişimler', ['Ülkenin yüzölçümü, ve nüfus yoğunluğu ile ilçe sayısı', 'Ülkenin bayrak rengi', 'Haberin yayın saati'], 'Ortalamadaki artış üst uçta yoğunlaşmış olabilir; dilimlere göre değişim, \'herkes\' için iyileşme olup olmadığını gösterir.'),
  ('Bir klinik deneme, ara analizde ilacın belirgin yararlı göründüğünü saptayıp erken durduruluyor. Bu tür erken durdurulan çalışmalar için hangisi genellikle söylenir?', 'Etki büyüklüğünü olduğundan fazla gösterme eğilimindedir', ['Etki büyüklüğünü olduğundan düşük gösterme eğilimindedir, çünkü erken durdurma kesin kanıt sağlar', 'Etkiyi her zaman gerçeğe eşit bildirir', 'Hiçbir koşulda yayımlanamaz'], 'Ara analizde rastlantısal olarak uç iyi çıkan sonuçlar yakalandığında çalışma durdurulursa, bildirilen etki gerçek etkiden büyük olabilir. Bu, kazananın laneti ve ortalamaya dönüşle ilişkilidir.'),
  ('Bir salgın döneminde resmî \'virüse bağlı ölüm\' sayısı 10.000 iken, aynı dönemde beklenen ölümden fazla görülen toplam ölüm 18.000\'dir. Aradaki fark için en olası açıklama hangisidir?', 'Testsiz ve dolaylı ölümler resmî sayıda yok', ['Resmî sayının daima fazla sayılması', 'Beklenen ölüm sayısının hiç hesaplanamaması', 'Fazla ölümlerin tamamının kayıt hatası olması'], 'Resmî sayı yalnızca doğrulanmış vakaları içerir; testsiz ölümler ve sağlık hizmetine erişimin bozulmasına bağlı ölümler dışarıda kalabilir. Aşırı ölüm bu farkı yakalar.'),
  ('Çevrimiçi ürün yorumlarında çoğu kişi 5 ya da 1 yıldız veriyor, orta puanlar azdır. Bu \'J biçimli\' dağılımın başlıca nedeni nedir?', 'Gönüllü uç deneyimlerin yazılması', ['Orta düzey deneyimlerin hiç bulunmaması', 'Yorumların yalnızca rastgele seçilmesi', 'Yıldız sisteminin bozuk olması'], 'Yorum yazmak gönüllüdür ve duygusal uçlar bunu daha çok tetikler. Bu nedenle puan ortalaması, tüm müşterilerin deneyimini yansıtmayabilir.'),
  ('Bir uygulama mağazasında iki oyunun ortalama puanı 4,5\'tir; biri 20 kişiden, diğeri 20 bin kişiden alınmıştır. Oyunları sıralarken hangi yaklaşım daha mantıklıdır?', 'Puanı yorum sayısına göre düzeltmek', ['Yalnızca ham ortalamaya göre sıralamak', 'Yalnızca yorum sayısına göre sıralamak', 'Rastgele sıralamak'], 'Küçük n\'li ortalamalar daha belirsizdir; belirsizliği hesaba katan düzeltmeler (ör. alt güven sınırı) daha adil sıralama verir.'),
  ('Bir web sitesi yeni bir tasarımı test ediyor ve ilk iki günde kullanıcı etkileşiminde yükseliş görüyor; ancak iki hafta sonra fark kayboluyor. Bu örüntü en iyi hangi olguyla açıklanır?', 'Yenilik etkisi; merak geçicidir', ['Büyük sayılar yasası; örneklem büyüdükçe fark artar', 'Kümelenme yanılsaması; fark yoktur', 'Yanıtsızlık yanlılığı; kullanıcılar yanıt vermez'], 'Yeni arayüz geçici merak yaratır; etki sönümlenir. Kısa süreli A/B testleri, kalıcı etkiyi olduğundan büyük gösterebilir.'),
  ('Bir site, A tasarımını hafta içi, B tasarımını hafta sonu göstererek ikisini karşılaştırıyor. Bu tasarımın başlıca sorunu nedir?', 'Karıştırıcı: hafta içi–sonu farkı', ['İki tasarımın hiç görünmemesi', 'Örneklem sayısının sonsuz olması', 'Hafta içi kullanıcıların sayılamaması'], 'Zaman, kullanıcı türü ve davranışı değiştirir; gruplar aynı koşulda rastgele atanmadıkça tasarım etkisi ayrılamaz. A/B testlerinde atama eşzamanlı ve rastgele olmalıdır.'),
  ('Bir reklam kampanyası sonrasında satışlar artıyor, ancak kampanyadan birkaç hafta sonra satışlar normal düzeyin altına düşüyor. Bu durum hangi yorumu destekler?', 'Satışlar öne çekilmiştir', ['Kampanya her zaman kalıcı büyüme yaratmıştır', 'Satışlar rastgele değişmiştir', 'Müşteri sayısı sonsuzdur'], 'Kampanya, bir kısım alımı erkene çekmiş olabilir; sonraki düşüş bunu telafi eder. Net etki için kampanya sonrası dönemi de içeren daha uzun bir karşılaştırma gerekir.'),
  ('Bir araştırma, orta miktarda kahve tüketenlerin ölüm oranının hem hiç içmeyenlerden hem çok içenlerden düşük olduğunu bildiriyor. Bu \'U biçimli\' ilişki için hangisi söylenebilir?', 'Doz-yanıt doğrusal olmayabilir', ['İlişki her zaman doğrusal olmak zorundadır', 'Hiç içmeyenlerle çok içenler birbirinin aynısıdır', 'Kahve hiçbir değişkenle ilişkili olamaz'], 'Etki dozla birlikte artıp sonra azalabilir. Doğrusal bir korelasyon katsayısı, böyle bir ilişkiyi yakalayamaz.'),
  ('Bir şirket, deneyimsiz çalışanların işe giriş eğitimi sonrası performansının, deneyimlilerden daha çok arttığını görüyor. Bu farkı yorumlarken hangisi dikkate alınmalıdır?', 'Düşük başlangıçtan artış kolaydır', ['Deneyimlilerin eğitimden hiç yararlanamayacağı', 'Deneyimsizlerin sayısının her zaman daha az olması', 'Performansın ölçülememesi'], 'Düşük başlayan grupta yükselmek daha kolaydır; ayrıca uç düşük performansın kısmen şans olması ortalamaya dönüşü getirir. Eğitim etkisi, karşılaştırma grubuyla ölçülmelidir.'),
  ('Bir araştırmacı çok sayıda yeni çalışmayı derlemek yerine, yalnızca kendi laboratuvarında yürütülmüş üç çalışmayı derleyip \'literatür bunu destekliyor\' diyor. Bu uygulamada hangi sorun vardır?', 'Seçici derleme; olumsuz sonuçlar dışarıda', ['Üç çalışmanın hiçbir zaman toplanamaması', 'Laboratuvar çalışmalarının geçersiz olması', 'Literatürün hiçbir zaman yayımlanmaması'], 'Tüm ilgili çalışmaları sistematik biçimde taramayan bir derleme yanlıdır. Sistematik derleme, arama stratejisi ve seçim ölçütlerini açıkça belirtir.'),
  ('Bir şirket, 100 bağımsız izleme alarmı çalıştırıyor ve her alarm sorun olmadığı hâlde günde %1 olasılıkla yanlış alarm veriyor. Günde beklenen yanlış alarm sayısı kaçtır?', '1', ['0,01, çünkü olasılık %1\'dir', '10, çünkü %1 on kez uygulanır', '100, çünkü alarm sayısı kadardır'], '100 × 0,01 = 1\'dir; her gün ortalama bir yanlış alarm beklenir. Çok sayıda izleme, küçük hata oranlarını sık yanlış alarma dönüştürür.'),
  ('Bir hastalıkta 2×2 tabloya göre maruz kalanların 40\'ında hastalık var, 60\'ında yok; maruz kalmayanların 20\'sinde hastalık var, 80\'inde yok. Odds oranı yaklaşık kaçtır?', 'Yaklaşık 2,7', ['Tam olarak 2, çünkü risk oranı odds oranına eşittir', 'Yaklaşık 1,5', 'Yaklaşık 4'], 'Odds oranı (40/60) / (20/80) = 0,667 / 0,25 ≈ 2,67\'dir; risk oranı ise 0,40 / 0,20 = 2\'dir. Yaygın olaylarda odds oranı, risk oranını abartır.'),
  ('Bir şehir \'trafik kazalarını %30 azalttık\' derken kaza sayıları iki yılın ortalamasına göre bir sonraki yıla kıyaslanıyor ve ilk yıl, rekor kaza yılıdır. Bu düşüşün etkisini abartma riski nedir?', 'Rekor yıl taban; ortalamaya dönüş', ['Rekor yıl taban alındığında düşüş küçük görünür', 'Kaza sayıları hiçbir zaman değişmez', 'Yüzde azalış hesaplanamaz'], 'Uç yüksek bir yıl, doğal olarak ortalamaya doğru geri döner. Etki ölçülürken uzun dönem ortalaması ya da karşılaştırma bölgeleri kullanılmalıdır.'),
  ('Bir araştırmacı, sosyal medya kullanım süresi ile kaygı puanı arasında r = 0,35 bulur ve iki yönlü bir nedensellik olasılığını tartışır. Hangi ek veri nedensel yönü ayırt etmeye en çok yardımcı olur?', 'Aynı kişileri izleyen boylamsal veri', ['Daha fazla kişiyi bir kez ölçmek', 'Kaygı puanını yuvarlamak', 'Kullanım süresini ortalamaya çevirmek'], 'Zaman sırası, birinin diğerini öngörüp öngörmediğini gösterir. Tek seferlik kesit veri, yönü ayırt edemez.'),
  ('Bir lig, takımları 20 maçlık sezon sonunda sıralıyor ve iki takımın puan farkı 1 puandır. Bir maç sonucu şansla değişirse sıralama değişebilir. Sıralama kararı için hangi ek bilgi en anlamlıdır?', 'Farkın şans değişkenliğine oranı', ['Takımların logo renkleri, ve takımların şehir nüfusu', 'Takımların kuruluş yılı', 'Hakemlerin boyları'], 'Küçük puan farkları ölçüm gürültüsü içinde kalabilir. Sıralamanın güvenilirliği, farkın şans kaynaklı değişkenlikten ne kadar büyük olduğuyla değerlendirilir.'),
  ('Bir şirket, yeni bir eğitimin etkisini ölçmek için eğitimi gönüllü olanlarla gönüllü olmayanları karşılaştırıyor ve gönüllülerin daha başarılı olduğunu görüyor. Eğitim öncesi performansı da biliyorsa hangi analiz karşılaştırmayı iyileştirir?', 'İlk performansı sabitleyerek karşılaştırmak', ['Yalnızca eğitim sonrası performansı karşılaştırmak', 'Gönüllüleri analizden çıkarmak', 'Eğitim öncesi performansı yok saymak'], 'Gönüllüler başlangıçta farklıdır; başlangıç performansını sabitlemek bu farkı azaltır. Yine de ölçülmeyen motivasyon gibi etkenler kalabilir.'),
  ('Bir şirket, geçmiş 5 yılda tamamlanan projelerin ortalama süresini 14 ay bulmuş; hâlâ süren 6 proje bu hesaba alınmamıştır. Gerçek ortalama süre için hangisi söylenebilir?', 'Gerçek süreden kısa kalır', ['Gerçek süre bu ortalamaya eşittir', 'Gerçek süre 14 aydan kesinlikle kısadır', 'Süren projeler ortalamaya hiçbir etki yapamaz'], 'Henüz bitmeyen projeler daha uzun sürmekte olduğundan hesaba katılmadıklarında ortalama düşük çıkar. Bu, sağa sansürlü verinin klasik bir sorunudur.'),
  ('Bir fon yöneticisi geçmiş 10 yıllık veride 200 farklı parametre kombinasyonunu deneyip en yüksek getiriyi veren kombinasyonu raporluyor. Bu rapor için doğru ifade hangisidir?', 'Getiri şişmiştir; deneme sayısı bildirilmeli', ['Raporlanan getiri gelecekte kesinlikle tekrarlanır', 'Deneme sayısı rapor için önemsizdir', 'Parametre sayısı sonuca hiçbir şekilde etki etmez'], 'En iyi sonucu seçmek, şans payını da seçer. Kaç kombinasyon denendiği bilinmeden getirinin gerçek olup olmadığı değerlendirilemez.'),
  ('Bir araştırmacı, sürekli bir değişkeni (örneğin kaygı puanı) medyandan \'düşük\' ve \'yüksek\' diye iki gruba ayırıp gruplar arası fark testi yapıyor. Bu işlemin başlıca sakıncası nedir?', 'Bilgi kaybı; güç azalır', ['Veri sayısı artar ve güç artar', 'Değişkenin dağılımı normale yaklaşır', 'Hiçbir bilgi kaybı olmaz'], 'İki parçaya bölmek, ince ayrımları siler; medyanın iki yanındaki neredeyse aynı kişiler farklı gruplara sayılır. Bu nedenle istatistiksel güç düşer.'),
  ('Bir kişi \'nüfusun %60\'ı spor yapıyor, %70\'i kitap okuyor\' bilgisini verip \'hem spor yapan hem kitap okuyan en az %30\'dur\' diyor. Bu sonuç doğru mudur?', 'Evet; örtüşme en az %30', ['Hayır; örtüşme sıfır olabilir', 'Hayır; örtüşme en fazla %10\'dur', 'Evet, ancak yalnızca iki grup bağımsızsa'], 'Spor yapan ve kitap okuyanların toplamı %130 olup %100\'ü aştığından, en az 60 + 70 − 100 = %30 kişi iki grupta birden bulunur.'),
  ('Ham doğum hızı (bin kişide doğum) ile toplam doğurganlık hızı (kadın başına çocuk sayısı) arasındaki fark nedir?', 'Ham hız tüm nüfusa, doğurganlık kadınlara göre', ['İkisi tamamen aynı ölçüdür', 'Ham hız yalnız kadınları, doğurganlık hızı tüm nüfusu kapsar', 'Doğurganlık hızı ölümleri sayar'], 'Ham doğum hızının paydası tüm nüfustur ve yaş yapısından etkilenir; toplam doğurganlık hızı ise yaşa özgü doğurganlıkların toplamıdır.'),
  ('Hasher ve arkadaşlarının 1977 çalışmasında, katılımcılara aynı ifadeler birkaç kez gösterilince ifadelerin doğru olduğuna dair güvenleri arttı; ifadelerin gerçekte doğru olup olmadığı değişmemişti. Bu olgunun adı nedir?', 'Yanılsamalı doğruluk etkisi', ['Sonradan bilme yanlılığı, çünkü sonuç bilinince tahmin değişir', 'Çıpalama etkisi, çünkü ilk sayı yargıyı belirler', 'Barnum etkisi, çünkü genel ifadeler kişiye özgü sanılır'], 'Bir ifadeyi tekrar duymak, ona aşinalık ve dolayısıyla doğruluk hissi verir. Bu nedenle yanlış bilgiler, tekrarlandıkça daha inandırıcı görünebilir.'),
  ('Baker ve Emery\'nin 1993 araştırmasında evlenecek çiftlerin çoğu boşanma oranının yaklaşık %50 olduğunu doğru biliyor, ancak kendi boşanma olasılıklarını sıfıra yakın buluyordu. Bu eğilim hangi olguyla açıklanır?', 'İyimserlik yanlılığı', ['Büyük sayılar yasası; oranlar zamanla sabitlenir', 'Hayatta kalma yanlılığı; yalnız başarılı evlilikler görülür', 'Savcı yanılgısı; koşullu olasılık ters çevrilir'], 'İnsanlar taban oranını bilse de kendileri için istisna olduklarını varsayar. Bu, planlama ve risk değerlendirmesinde sistematik iyimserliğe yol açar.'),
  ('Shafir, Diamond ve Tversky\'nin deneyinde insanlar, enflasyon yokken %2 maaş artışını, %4 enflasyon varken %5 maaş artışına göre daha cazip buldu. Bu tercih hangi hatayı gösterir?', 'Para yanılsaması', ['Kumarbaz yanılgısı', 'Hayatta kalma yanlılığı', 'Kümelenme yanılsaması'], 'İkinci durumda reel artış yaklaşık %1, birincide %2\'dir; ancak nominal olarak %5 daha yüksek göründüğü için çoğu kişi onu seçer. Reel değer, nominal değerden farklıdır.'),
  ('Bir gruptan \'bir ülkenin nüfusu için %90 olasılıkla içinde kaldığınız bir aralık verin\' denildiğinde çoğu kişinin verdiği aralık gerçek değeri yalnızca yaklaşık yarı oranında içeriyor. Bu eğilim hangi adla anılır?', 'Aşırı kesinlik; aralıkları olduğundan dar belirlemek', ['Aşırı belirsizlik; aralıkları olduğundan geniş belirlemek', 'İyi kalibrasyon', 'Yanıtsızlık yanlılığı'], 'Gerçekten %90 kapsayıcı aralıklar daha geniş olmalıdır. İnsanların aralıkları dar tutması, bilgiye gereğinden fazla güvenmeleri anlamına gelir.'),
  ('Bir araştırmacı, ankette \'bilmiyorum\' yanıtını veren 200 kişiyi silip kalanların oranlarını raporluyor. Bu işlem hangi durumda sonucu yanıltır?', 'Farklı özellikteyseler', ['\'Bilmiyorum\' diyenler her zaman rastgele ise', 'Sonuç yüzde olarak verilmemişse', 'Kalan kişi sayısı çok fazlaysa'], 'Kararsızlar ya da bilmeyenler belirli bir grubu oluşturuyorsa, bunları silmek oranları çarpıtır. Bu yanıtların ayrı kategori olarak raporlanması daha dürüsttür.'),
  ('İlk hafta 1000 kişiyle yapılan bir A/B testinde yeni tasarım %10 daha fazla satış getiriyor. Aynı yeni tasarım ve aynı kullanıcı kitlesiyle yapılan ikinci denemede fark %3 bulunuyor. Bu iki sonuç farkı için hangisi beklenir?', 'İlk sonuç şansla uca düşmüştür', ['İkinci deneme hatalıdır', 'İlk deneme her zaman gerçektir', 'Tasarımın etkisi sıfır olmuştur'], 'Küçük ve tek bir denemede en yüksek çıkan fark, kısmen şanstır. Yeniden denemede fark ortalamaya doğru çekilir.'),
  ('Bir veri raporuna göre \'on yıl önce %20 olan işsizlik %10\'a düştü\'. Aynı dönemde işgücüne katılım oranı %60\'tan %45\'e düşmüştür. İşsizlik oranının düşüşü için hangisi söylenebilir?', 'İş aramayı bırakanlar işgücü dışına çıkmıştır', ['Düşüş tamamen yeni istihdamdan kaynaklanır, ve bu kişiler işsiz sayılmaya devam eder', 'Katılım oranı işsizlikle ilgili değildir', 'İşsizlik oranı hiçbir tanımda değişmez'], 'İşsizlik oranının paydası işgücüdür; vazgeçen kişiler işgücünden çıkarsa oran, iş bulunmadan da düşer. Katılım oranı ile birlikte okunmalıdır.'),
  ('Bir araştırma, kadınların erkeklerden saatlik ortalama %20 daha az kazandığını bildiriyor. Aynı mesleklerde, aynı deneyim ve çalışma saatlerinde karşılaştırıldığında fark %5\'e iniyor. Bu iki sayı için doğru yorum hangisidir?', 'Ham fark dağılımı da içerir', ['Ham fark yanlıştır ve yok sayılmalıdır', 'Ayarlı fark yanlıştır ve yok sayılmalıdır', 'İki sayı aynı olgunun aynı ölçüsüdür'], 'Ham ve ayarlı fark farklı sorulara yanıt verir: ham fark toplam eşitsizliği, ayarlı fark benzer koşullardaki farkı gösterir. İkisi de bilgi taşır ve birlikte yorumlanmalıdır.'),
  ('Bir kentte polis kayıtlarındaki hırsızlık sayısı düşüyor, ancak mağduriyet anketlerinde hırsızlığa uğradığını söyleyenlerin oranı sabit kalıyor. Bu çelişkiyi en iyi hangisi açıklar?', 'Bildirme oranı düşmüş olabilir', ['Anketlerin hiç kimseye sorulmaması', 'Polis kayıtlarının her suçu eksiksiz içermesi', 'Hırsızlığın ölçülememesi'], 'Kayıtlar, bildirilen ve kaydedilen olayları gösterir; mağduriyet anketleri ise bildirilmeyenleri de yakalar. İki kaynağın farklılaşması, bildirme davranışı değişimine işaret edebilir.'),
  ('Bir şirketin aylık satışlarının 3 aylık hareketli ortalaması, satışlardaki gerçek bir düşüşü ne zaman gösterir?', 'Geç gösterir', ['Erken gösterir; çünkü gürültüyü büyütür', 'Tam zamanında gösterir', 'Asla göstermez'], 'Hareketli ortalama geçmiş değerleri de içerdiğinden değişim ortalamaya ancak sonraki aylarda yansır. Gürültü azalır ama gecikme artar.'),
  ('Bir hastalık çalışmasında 5 kişi 10 yıl, 2 kişi 25 yıl izlenmiş ve toplamda 2 vaka görülmüştür. Kişi-yıl başına hastalık hızı kaçtır?', '100 kişi-yılda yaklaşık 2', ['100 kişi-yılda yaklaşık 28', '100 kişi-yılda yaklaşık 40', '100 kişi-yılda yaklaşık 14'], 'Toplam kişi-yıl 5 × 10 + 2 × 25 = 100\'dür; hız 2 / 100 = 100 kişi-yılda 2\'dir. Farklı süre izlenen kişilerde kişi-yıl, doğru paydadır.'),
  ('Bir araştırmada iki grubun hastalık sayıları aynı (10\'ar vaka) olmakla birlikte A grubunda 100 kişi 1 yıl, B grubunda 100 kişi 5 yıl izlenmiştir. Hastalık hızı bakımından ne söylenebilir?', 'A grubunun hızı B\'nin beş katıdır', ['İki grubun hızı eşittir, çünkü hızlar vaka sayısına bölünmez', 'B grubunun hızı A\'nın beş katıdır', 'Hız hesaplanamaz'], 'Vaka sayısı eşitken A\'nın kişi-yılı 100, B\'nin 500\'dür; hızlar 10/100 ve 10/500\'dür. Farklı izlem süresini hesaba katmayan sayım karşılaştırması yanıltır.'),
  ('Bir ülkede bütçe açığı bir yıl önceki 100 milyardan 80 milyara iniyor. Borç stoku hakkında hangisi doğrudur?', 'Borç azalmıyor, yavaş artıyor', ['Borç tamamen ödenmiştir', 'Borç 20 milyar azalmıştır', 'Borç sıfırlanmıştır'], 'Bütçe açığı bir akıştır; borç ise bunun birikimi (stok) olan değişkendir. Açık hâlâ pozitifse borç artmaya devam eder.'),
  ('Bir anketten \'katılımcıların %40\'ı evet dedi\' ve \'evet diyenlerin %60\'ı kadındı\' bilgileri veriliyor. Bir okuyucu \'kadınların %60\'ı evet dedi\' sonucunu çıkarıyor. Bu çıkarımın hatası nedir?', 'Paydalar karıştırılmıştır', ['Yüzdelerin 100\'e tamamlanması gerektiği', 'Kadınların ankete hiç katılmaması', 'İki yüzdenin çarpılamaması'], 'Evet diyenler içinde kadın oranı P(kadın | evet), kadınlar içinde evet oranı ise P(evet | kadın) olup farklı koşullu oranlardır.'),
  ('İki değerlendirici, aynı 100 çalışmayı puanlıyor; aralarındaki korelasyon 0,95\'tir ancak ikinci değerlendirici her çalışmaya birincisinden tam 10 puan fazla veriyor. \'İki değerlendirici uyumlu\' sonucu için hangisi söylenebilir?', 'Korelasyon uyum değildir', ['Uyum tamdır; çünkü korelasyon 0,95\'tir', 'Korelasyon düşüktür', 'Fark ölçülemez'], 'Korelasyon, doğrusal birlikte değişimi ölçer; sabit bir kayma korelasyonu bozmaz ama puanları farklı kılar. Uyum için mutlak farklara da bakılmalıdır.'),
  ('Bir kumar oyuncusu, her kayıptan sonra bahsi iki katına çıkararak sonunda bir kez kazanınca kaybı çıkaracağını ve 1 liralık kâr edeceğini söylüyor (martingale stratejisi). Sonlu bütçeyle bu stratejinin sorunu nedir?', 'Uzun kayıp serisi bütçeyi bitirebilir', ['Strateji her zaman kesin kazanç garantiler', 'Kayıp serileri hiçbir zaman yaşanmaz', 'Bahis iki katına çıktıkça kayıp olasılığı azalır'], 'Her bahsin kazanma olasılığı değişmez; ardışık kayıplar bahsi üstel biçimde büyütür ve sonlu bütçeyi tüketir. Sık küçük kazançlar, seyrek büyük kayıpla telafi edilemeyebilir.'),
  ('Bir yatırım stratejisi işlemlerin %90\'ında 1 lira kazandırıyor, %10\'unda 20 lira kaybettiriyor. Strateji için hangisi doğrudur?', 'Beklenen değeri negatiftir', ['Sık kazandığı için beklenen değeri pozitiftir', 'Beklenen değeri sıfırdır', 'Beklenen değeri +1,1 liradır'], '0,90 × 1 − 0,10 × 20 = −1,1\'dir. Kazanma sıklığı, kazanç ve kayıp büyüklüklerini hesaba katmadan başarıyı göstermez.'),
  ('Bir kumarhanede bir oyuncu bir gecede 5 bin lira kazanıyor ve \'kasa kaybediyor\' diyor. Uzun vadede kasanın avantajı varken kısa vadede oyuncunun kazanması neden mümkündür?', 'Kısa vadede değişkenlik büyüktür', ['Kasanın avantajı yalnızca yazılı kuraldır', 'Kısa vadede olasılıklar tersine döner', 'Uzun vadede kasa hiç kazanmaz'], 'Beklenen avantaj bahis başına küçük bir yüzdedir; kısa vadeli standart sapma ise büyüktür. Büyük sayılar yasası, avantajı ancak çok sayıda bahisten sonra belirgin kılar.'),
  ('Bir kamu kurumu, ölçüm cihazlarını \'bakım yaptırdıktan sonra kalibrasyon sapması azaldı\' diye raporluyor; bakımdan önceki ölçümler, sapması en yüksek cihazlardan seçilmişti. Bu rapor için hangisi söylenebilir?', 'Uçta seçildiğinden iyileşme beklenirdi', ['Bakım iyileşmeyi kesin olarak kanıtlar', 'İyileşme bakımdan bağımsızdır ve hiç gözlenmez', 'Sapması yüksek cihazlar hiçbir zaman değişmez'], 'Uç değerlerden seçilen cihazlar, ölçüm gürültüsü nedeniyle sonraki ölçümde ortalamaya yaklaşır. Bakımın etkisini ayırmak için bakım görmeyen benzer cihazlar karşılaştırılmalıdır.'),
];
